function drawScreenMovieTitle(ctx, title, width, height, color, glowColor, baseSize = 64) {
    const maxWidth = width * 0.84;
    const words = String(title || 'NOW SHOWING').trim().split(/\s+/);
    let fontSize = baseSize;
    let lines = [words.join(' ')];
    while (fontSize > 36) {
        ctx.font = `700 ${fontSize}px "Space Grotesk", sans-serif`;
        lines = [];
        let line = '';
        words.forEach(word => {
            const candidate = line ? `${line} ${word}` : word;
            if (line && ctx.measureText(candidate).width > maxWidth) {
                lines.push(line);
                line = word;
            } else {
                line = candidate;
            }
        });
        if (line) lines.push(line);
        if (lines.length <= 2 && lines.every(item => ctx.measureText(item).width <= maxWidth)) break;
        fontSize -= 2;
    }

    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `700 ${fontSize}px "Space Grotesk", sans-serif`;
    ctx.fillStyle = color;
    ctx.shadowColor = glowColor;
    ctx.shadowBlur = 24;
    const centerY = height * 0.48;
    const lineGap = fontSize * 1.08;
    lines.forEach((line, index) => {
        const y = centerY + (index - (lines.length - 1) / 2) * lineGap;
        ctx.fillText(line.toUpperCase(), width / 2, y, maxWidth);
    });
    ctx.restore();
}

function renderDynamicScreenCanvas(time) {
    const w = screenCanvas.width;
    const h = screenCanvas.height;

    if (screenChannel === 'custom' && customVideoEl.readyState >= 2) {
        sCtx.drawImage(customVideoEl, 0, 0, w, h);
        screenLightCenter.color.setHSL((time * 0.07) % 1, 0.75, 0.55);
        screenTexture.needsUpdate = true;
        return;
    }

    if (screenChannel === 'blockbuster') {
        // High-Octane Indian Blockbuster Trailer ("PUSHPA 2 / DEVARA 4K ATMOS")
        const pulse = Math.sin(time * 2.1) * 0.5 + 0.5;
        const bgGrad = sCtx.createRadialGradient(w * 0.5, h * 0.58, 30, w * 0.5, h * 0.5, w * 0.65);
        bgGrad.addColorStop(0, `hsl(${28 + pulse * 14}, 95%, 26%)`);
        bgGrad.addColorStop(0.55, `hsl(${12 + pulse * 10}, 85%, 11%)`);
        bgGrad.addColorStop(1, '#040509');
        sCtx.fillStyle = bgGrad;
        sCtx.fillRect(0, 0, w, h);

        // Dramatic Ocean / Fire Horizon Glow
        const horizonY = h * 0.72;
        const flare = sCtx.createLinearGradient(0, horizonY - 25, 0, h);
        flare.addColorStop(0, `rgba(255, 140, 30, ${0.4 + pulse * 0.25})`);
        flare.addColorStop(0.3, 'rgba(180, 35, 10, 0.35)');
        flare.addColorStop(1, '#030408');
        sCtx.fillStyle = flare;
        sCtx.fillRect(0, horizonY - 25, w, h - horizonY + 25);

        // Rising Fire Embers
        for (let em of emberParticles) {
            em.x += em.vx;
            em.y += em.vy;
            if (em.y < 0) { em.y = h; em.x = Math.random() * w; }
            if (em.x > w) em.x = 0;
            if (em.x < 0) em.x = w;

            sCtx.fillStyle = `rgba(255, ${150 + Math.floor(pulse * 80)}, 40, ${em.alpha})`;
            sCtx.beginPath();
            sCtx.arc(em.x, em.y, em.r, 0, Math.PI * 2);
            sCtx.fill();
        }

        // Anamorphic Gold Streak
        const streakY = h * 0.48 + Math.sin(time * 1.5) * 8;
        const sGrad = sCtx.createLinearGradient(0, streakY, w, streakY);
        sGrad.addColorStop(0, 'rgba(201, 168, 76, 0)');
        sGrad.addColorStop(0.5, `rgba(255, 215, 110, ${0.45 + pulse * 0.3})`);
        sGrad.addColorStop(1, 'rgba(201, 168, 76, 0)');
        sCtx.fillStyle = sGrad;
        sCtx.fillRect(0, streakY - 2, w, 4);

        // Blockbuster Title Typography
        sCtx.save();
        sCtx.textAlign = 'center';
        sCtx.fillStyle = '#fbbf24';
        sCtx.font = '700 14px "Space Grotesk", sans-serif';
        sCtx.fillText(`MD CINEWAVE • ${currentAudi.name.toUpperCase()}`, w / 2, h * 0.24, w * 0.84);

        const activeTitle = currentAudi.movieTitle || 'NOW SHOWING';
        drawScreenMovieTitle(sCtx, activeTitle, w, h, '#ffffff', '#f59e0b', 64);

        sCtx.save();
        sCtx.font = '600 15px "Inter", sans-serif';
        sCtx.textAlign = 'center';
        sCtx.fillStyle = '#fde68a';
        sCtx.fillText(`REAL-TIME 3D SEAT POV: ${activePOVSeatId}  •  DOLBY ATMOS 64-CH`, w / 2, h * 0.64, w * 0.84);
        sCtx.restore();

        // Sync Ambilight bounce to warm gold/crimson
        screenLightCenter.color.setHSL(0.08 + pulse * 0.03, 0.95, 0.55);
        screenLightLeft.color.setHSL(0.04, 0.9, 0.48);
        screenLightRight.color.setHSL(0.11, 0.9, 0.50);
        sCtx.restore();

    } else if (screenChannel === 'scifi') {
        const pulse = Math.sin(time * 1.4) * 0.5 + 0.5;
        const grad = sCtx.createRadialGradient(w * 0.5, h * 0.5, 20, w * 0.5, h * 0.5, w * 0.65);
        grad.addColorStop(0, `hsl(${192 + pulse * 25}, 90%, 24%)`);
        grad.addColorStop(0.5, `hsl(${265 - pulse * 20}, 82%, 10%)`);
        grad.addColorStop(1, '#03050a');
        sCtx.fillStyle = grad;
        sCtx.fillRect(0, 0, w, h);

        const cx = w * 0.5, cy = h * 0.48;
        for (let s of stars) {
            s.z -= 8.0;
            if (s.z <= 1) { s.z = 1024; s.x = Math.random() * w; s.y = Math.random() * h; }
            const k = 260 / s.z;
            const px = cx + (s.x - cx) * k;
            const py = cy + (s.y - cy) * k;
            if (px >= 0 && px <= w && py >= 0 && py <= h) {
                const size = (1 - s.z / 1024) * 3.8;
                sCtx.fillStyle = `hsla(${s.hue}, 100%, 80%, ${1 - s.z / 1024})`;
                sCtx.beginPath();
                sCtx.arc(px, py, size, 0, Math.PI * 2);
                sCtx.fill();
            }
        }

        drawScreenMovieTitle(sCtx, currentAudi.movieTitle || 'NOW SHOWING', w, h, '#ffffff', '#00f0ff', 60);
        sCtx.save();
        sCtx.textAlign = 'center';
        sCtx.fillStyle = '#cbd5e1';
        sCtx.font = '500 15px "Inter", sans-serif';
        sCtx.fillText(`NOW SHOWING  •  LIVE SIGHTLINE SIMULATION  •  ACTIVE SEAT: ${activePOVSeatId}`, cx, h * 0.64, w * 0.84);
        sCtx.restore();

        screenLightCenter.color.setHSL(0.52 + pulse * 0.05, 0.95, 0.55);
        screenLightLeft.color.setHSL(0.76, 0.85, 0.5);
        screenLightRight.color.setHSL(0.50, 0.85, 0.5);

    } else if (screenChannel === 'atmos') {
        sCtx.fillStyle = '#050811';
        sCtx.fillRect(0, 0, w, h);
        const bars = 44;
        const bw = (w - 160) / bars;
        for (let i = 0; i < bars; i++) {
            const amp = (Math.sin(time * 3.2 + i * 0.3) * 0.5 + 0.5) * (Math.cos(time * 1.7 - i * 0.15) * 0.4 + 0.6);
            const bh = Math.max(18, amp * (h * 0.62));
            const hue = 185 + (i / bars) * 90;
            sCtx.fillStyle = `hsl(${hue}, 95%, 58%)`;
            sCtx.fillRect(80 + i * bw, (h - bh) / 2, bw - 4, bh);
        }
        sCtx.fillStyle = '#ffffff';
        sCtx.textAlign = 'center';
        sCtx.font = '700 32px "Space Grotesk", sans-serif';
        sCtx.fillText(`DOLBY ATMOS 64-CHANNEL ACOUSTIC FIELD • SEAT ${activePOVSeatId}`, w / 2, 54);
        screenLightCenter.color.setHSL((time * 0.15) % 1, 0.9, 0.55);

    } else if (screenChannel === 'calibration') {
        sCtx.fillStyle = '#070b12';
        sCtx.fillRect(0, 0, w, h);
        sCtx.strokeStyle = 'rgba(0, 240, 255, 0.28)';
        sCtx.lineWidth = 1.5;
        for (let x = 0; x <= w; x += 64) { sCtx.beginPath(); sCtx.moveTo(x, 0); sCtx.lineTo(x, h); sCtx.stroke(); }
        for (let y = 0; y <= h; y += 64) { sCtx.beginPath(); sCtx.moveTo(0, y); sCtx.lineTo(w, y); sCtx.stroke(); }
        sCtx.strokeStyle = '#C9A84C';
        sCtx.lineWidth = 3;
        sCtx.beginPath(); sCtx.arc(w / 2, h / 2, 135, 0, Math.PI * 2); sCtx.stroke();
        sCtx.fillStyle = '#ffffff';
        sCtx.textAlign = 'center';
        sCtx.font = '700 34px "Space Grotesk", sans-serif';
        sCtx.fillText(`THX / IMAX SIGHTLINE CALIBRATION • SEAT ${activePOVSeatId}`, w / 2, h * 0.46);
    }

    screenTexture.needsUpdate = true;
}

