function applyOverviewFieldOfView() {
    const aspect = Math.max(0.25, container.clientWidth / Math.max(1, container.clientHeight));
    const targetFov = 62;
    // A portrait viewport loses horizontal coverage much faster than
    // it gains vertical coverage. Raise the overview eye and lower its
    // aim point progressively on narrow screens so the room width is
    // seen at a steeper angle without exceeding the lens limit.
    const portraitBias = THREE.MathUtils.clamp((1.12 - aspect) / 0.82, 0, 1);
    const responsiveCamera = overviewBaseCamera.clone();
    // Leave clearance below the suspended ceiling and projector housing.
    responsiveCamera.y = Math.min(auditoriumRoomHeight * 0.82,
        responsiveCamera.y + auditoriumRoomHeight * 0.3 * portraitBias);
    const responsiveTarget = auditoriumCenterTarget.clone();
    responsiveTarget.y = Math.max(0.35,
        responsiveTarget.y - auditoriumRoomHeight * 0.13 * portraitBias);
    auditoriumOverviewTarget.copy(responsiveTarget);
    const responsiveForward = responsiveTarget.clone().sub(responsiveCamera).normalize();
    const responsiveRight = new THREE.Vector3().crossVectors(responsiveForward, new THREE.Vector3(0, 1, 0)).normalize();
    const responsiveUp = new THREE.Vector3().crossVectors(responsiveRight, responsiveForward).normalize();
    const tanVertical = Math.tan(THREE.MathUtils.degToRad(targetFov / 2)) / 1.08;
    const tanHorizontal = tanVertical * aspect;
    let backoff = 0;
    overviewBounds.forEach(point => {
        const relative = point.clone().sub(responsiveCamera);
        const depth = relative.dot(responsiveForward);
        backoff = Math.max(backoff,
            Math.abs(relative.dot(responsiveUp)) / tanVertical - depth,
            Math.abs(relative.dot(responsiveRight)) / tanHorizontal - depth);
    });
    // Keep the camera inside the rear wall with a little clearance.
    // If an unusually narrow viewport cannot fit within the room,
    // widen the lens only after using all available rear concourse.
    const maxBackoff = responsiveForward.z < -0.001
        ? Math.max(0, (auditoriumRearWallZ - 0.65 - responsiveCamera.z) / -responsiveForward.z)
        : 0;
    backoff = Math.min(Math.max(0, backoff), maxBackoff);
    auditoriumOverviewCamera.copy(responsiveCamera).addScaledVector(responsiveForward, -backoff);
    const forward = auditoriumOverviewTarget.clone().sub(auditoriumOverviewCamera).normalize();
    const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
    const up = new THREE.Vector3().crossVectors(right, forward).normalize();
    let horizontalSlope = 0;
    let verticalSlope = 0;
    overviewBounds.forEach(point => {
        const relative = point.clone().sub(auditoriumOverviewCamera);
        const depth = relative.dot(forward);
        if (depth <= 0.25) return;
        horizontalSlope = Math.max(horizontalSlope, Math.abs(relative.dot(right)) / depth);
        verticalSlope = Math.max(verticalSlope, Math.abs(relative.dot(up)) / depth);
    });
    const requiredSlope = Math.max(verticalSlope, horizontalSlope / aspect);
    const fittedFov = THREE.MathUtils.radToDeg(2 * Math.atan(requiredSlope * 1.08));
    auditoriumOverviewFov = Number.isFinite(fittedFov)
        ? THREE.MathUtils.clamp(fittedFov, 32, 72) : targetFov;
    if (cameraMode === 'overview') {
        cameraTargetPos.copy(auditoriumOverviewCamera);
        desiredLookAtTarget.copy(auditoriumOverviewTarget);
        setCameraFieldOfView(auditoriumOverviewFov);
    }
}

