function buildParametricAuditorium(config) {
    const buildStartedAt = performance.now();
    // Release generated geometry from the previous layout while keeping
    // global palette materials and the shared movie texture alive.
    const keepMaterials = new Set([matStdAvail, matVipAvail, matReclinerAvail,
        matSelectedCart, matActivePOV, matOccupied, matArmrest, matSeatInset, matSeatStitch]);
    const oldGeometries = new Set();
    seatGeometryVariants.forEach(v=>{oldGeometries.add(v.near);oldGeometries.add(v.far);});
    seatGeometryVariants = [];
    const oldMaterials = new Set();
    const oldTextures = new Set();
    auditoriumGroup.traverse(object => {
        if (!object.isMesh) return;
        if (object.geometry) oldGeometries.add(object.geometry);
        const materials = Array.isArray(object.material) ? object.material : [object.material];
        materials.forEach(material => {
            if (material && !keepMaterials.has(material)) {
                oldMaterials.add(material);
                if (material.map && material.map !== screenTexture && material.map !== seatFabricTexture) oldTextures.add(material.map);
            }
        });
    });
    oldGeometries.forEach(geometry => geometry.dispose());
    oldMaterials.forEach(material => material.dispose());
    oldTextures.forEach(texture => { if (texture !== seatFabricTexture) texture.dispose(); });
    // Clear existing 3D objects
    while (auditoriumGroup.children.length > 0) {
        auditoriumGroup.remove(auditoriumGroup.children[0]);
    }
    interactiveSeatMeshes.length = 0;
    seatRegistry.clear();
    exitDoorsList.length = 0;
    architecturalAccentMaterials = [];

    const rows = config.rows;
    const visual = config.visual || {};
    const architecture = (config.referenceProfile || {}).architecture || {};
    const wallProfiles = architecture.wall_profiles || {};
    const leftWallProfile = wallProfiles.left || {};
    const rightWallProfile = wallProfiles.right || {};
    const seatProfile = architecture.seat_profile || {};
    const seatBaseColor = architecture.seat_color || visual.seat_color || '#51252d';
    const wallBaseColor = architecture.wall_color || visual.wall_color || '#11151d';
    const trimBaseColor = architecture.trim_color || visual.trim_color || '#c9a84c';
    const lightingBaseColor = architecture.lighting_color || trimBaseColor;
    const panelBaseColor = architecture.panel_color || '#121826';
