    const geometry = config.geometry || {};
    const physicalRoom = geometry.room || {};
    const physicalScreen = geometry.screen || {};
    const rowPositions = geometry.rows || [];
    const widestRow = Math.max(1, ...config.rowDefs.map(row => row.count * row.seatSpan * 0.62 + row.aislesAfter.length * 0.85 + row.offset * 0.62));
    const hallHalfWidth = Math.max(widestRow / 2 + 2.5, Number(physicalRoom.width || widestRow + 5) / 2);
    const rowSpacing = Number(config.rowSpacing || 1.15);
    const stadiumSlope = Number(config.stadiumSlope || 0.18);
    const farthestRowZ = Math.max(8, ...rowPositions.map(p => Number(p.z || 0)));
    const rearRowY = Math.max(0.35, ...rowPositions.map(p => Number(p.y || 0)));
    // Older app workers and pre-geometry layout payloads may not send
