    auditoriumHalfWidth = hallHalfWidth;
    auditoriumRoomHeight = roomHeight;

    // 1. Giant Curved Cinema Screen
    const configuredCurve = Number(physicalScreen.curve ?? ((physicalScreen.surface === 'flat' || physicalScreen.surface === 'led') ? 0 : (config.screenCurve ?? 0.3)));
    const thetaLength = (physicalScreen.surface === 'flat' || physicalScreen.surface === 'led' || configuredCurve === 0) ? 0 : Math.max(0.01, configuredCurve * Math.PI);
    const radius = thetaLength ? Math.max(8, Number(physicalScreen.width || config.screenWidth || 18) / thetaLength) : 0;
    // Flip the auditorium so the screen faces into the room from the -Z end.
