    const sideCameraX = hallHalfWidth * 0.76;
    auditoriumLeftCamera.set(-sideCameraX, Math.max(2.6, roomHeight * 0.42), hallCenterZ * 0.72);
    auditoriumRightCamera.set(sideCameraX, Math.max(2.6, roomHeight * 0.42), hallCenterZ * 0.72);
    auditoriumScreenCamera.set(0, Math.max(3.0, Math.min(roomHeight * 0.52, rearRowY + 1.4)), auditoriumRearWallZ - Math.max(2, hallDepth * 0.06));
    const overviewTarget = new THREE.Vector3(0, screenY + roomHeight * 0.2, hallCenterZ * 0.34);
    const forward = overviewTarget.clone().sub(auditoriumOverviewCamera).normalize();
    const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
    const up = new THREE.Vector3().crossVectors(right, forward).normalize();
overviewBounds.length = 0;
    [-hallHalfWidth * 0.94, hallHalfWidth * 0.94].forEach(x => {
        [0.05, roomHeight * 0.92].forEach(y => {
            [screenSurfaceZ, farthestRowZ].forEach(z => overviewBounds.push(new THREE.Vector3(x, y, z)));
