    });
    [-screenWidthM / 2, screenWidthM / 2].forEach(x => {
        [screenBottomM, screenBottomM + screenHeightM].forEach(y =>
            overviewBounds.push(new THREE.Vector3(x, y, screenSurfaceZ)));
