    auditoriumCenterTarget.copy(overviewTarget);
    overviewBaseCamera.copy(auditoriumOverviewCamera);
    overviewForward.copy(overviewTarget).sub(overviewBaseCamera).normalize();
    overviewRight.copy(forward);
    overviewUp.copy(up);
    applyOverviewFieldOfView();
    camera.far = Math.max(160, hallDepth + radius * 2 + 60);
    camera.updateProjectionMatrix();
    currentLookAtTarget.copy(screenCenterTarget);
    desiredLookAtTarget.copy(screenCenterTarget);
    const screenGeo = thetaLength
        ? new THREE.CylinderGeometry(radius, radius, screenHeightM, 64, 1, true, thetaStart, thetaLength)
