    const frameGeo = new THREE.CylinderGeometry(radius + 0.16, radius + 0.16, screenHeightM + 0.5, 64, 1, true, thetaStart - 0.01, thetaLength + 0.02);
        frameGeo.scale(-1, 1, 1);
