                linearSconce ? roomHeight * 0.48 : roomHeight * 0.56,
                z + (linearSconce ? (sconceGeometry.parameters.depth || 1.65) / 2 : 0));
            transform.updateMatrix();
            sconceInstances.setMatrixAt(panelIndex, transform.matrix);
            sconceInstances.count = panelIndex + 1;

            transform.position.set(wallX - side * 0.48, roomHeight * 0.72, z);
            transform.updateMatrix();
            speakerInstances.setMatrixAt(panelIndex, transform.matrix);
            speakerInstances.count = panelIndex + 1;
            transform.position.set(wallX - side * 0.72, roomHeight * 0.72, z);
            transform.updateMatrix();
            speakerLedInstances.setMatrixAt(panelIndex, transform.matrix);
            speakerLedInstances.count = panelIndex + 1;
        });
        [panelInstances, detailInstances, accentInstances, sconceInstances, speakerInstances, speakerLedInstances].forEach(mesh => {
            mesh.instanceMatrix.needsUpdate = true;
        });
        [
            [roomHeight * 0.18, 0],
            [roomHeight * 0.88, 0]
        ].forEach(([y], borderIndex) => {
            transform.position.set(wallX - side * 0.31, y, hallCenterZ);
            transform.updateMatrix();
            borderInstances.setMatrixAt(borderIndex, transform.matrix);
        });
        borderInstances.instanceMatrix.needsUpdate = true;
    }

    // Rear Projection Booth Wall & Volumetric Light Cone
    const backWallGeo = new THREE.BoxGeometry(hallHalfWidth * 2.1, roomHeight, 1);
    const backWall = new THREE.Mesh(backWallGeo, wallMat);
    backWall.position.set(0, roomHeight / 2, auditoriumRearWallZ);
    auditoriumGroup.add(backWall);

    const beamGeo = new THREE.ConeGeometry(7.8, hallDepth, 32, 1, true);
    const beamMat = new THREE.MeshBasicMaterial({
        color: 0x88ddff,
        transparent: true,
        opacity: 0.04,
        side: THREE.DoubleSide,
        depthWrite: false
    });
    const beamMesh = new THREE.Mesh(beamGeo, beamMat);
    beamMesh.rotation.x = -Math.PI / 2;
    beamMesh.position.set(0, roomHeight * 0.82, hallCenterZ);
    auditoriumGroup.add(beamMesh);

    // 3. BUILD 4 ILLUMINATED 3D EMERGENCY EXIT WAY DOORS (EXIT 1 - EXIT 4)
    const exitSpecs = [
        { id: 'EXIT_FL', name: 'EXIT 1 (Front Left)', shortName: 'EXIT 1', side: 'Left', x: -hallHalfWidth + 0.35, y: 0.2, z: screenSurfaceZ + 3.2, rotY: Math.PI / 2 },
        { id: 'EXIT_FR', name: 'EXIT 2 (Front Right)', shortName: 'EXIT 2', side: 'Right', x: hallHalfWidth - 0.35, y: 0.2, z: screenSurfaceZ + 3.2, rotY: -Math.PI / 2 },
        { id: 'EXIT_RL', name: 'EXIT 3 (Rear Left)', shortName: 'EXIT 3', side: 'Left', x: -hallHalfWidth + 0.35, y: 0.2, z: auditoriumRearWallZ - 2.2, rotY: Math.PI / 2 },
        { id: 'EXIT_RR', name: 'EXIT 4 (Rear Right)', shortName: 'EXIT 4', side: 'Right', x: hallHalfWidth - 0.35, y: 0.2, z: auditoriumRearWallZ - 2.2, rotY: -Math.PI / 2 }
    ];

    exitSpecs.forEach(ex => {
        const exGroup = new THREE.Group();
        exGroup.position.set(ex.x, ex.y, ex.z);
        exGroup.rotation.y = ex.rotY;

        // Heavy Acoustic Exit Door Frame
        const doorGeo = new THREE.BoxGeometry(1.75, 2.6, 0.18);
        const doorMat = new THREE.MeshStandardMaterial({ color: 0x071712, emissive: 0x032217, roughness: 0.5 });
        const doorMesh = new THREE.Mesh(doorGeo, doorMat);
        doorMesh.position.y = 1.3;
        exGroup.add(doorMesh);

        // Glowing Emerald Border Frame
        const borderGeo = new THREE.BoxGeometry(1.88, 2.72, 0.12);
        const borderMat = new THREE.MeshBasicMaterial({ color: 0x10b981 });
        const borderMesh = new THREE.Mesh(borderGeo, borderMat);
        borderMesh.position.set(0, 1.3, -0.02);
        exGroup.add(borderMesh);

        // Illuminated Push-Bar Handle
        const barGeo = new THREE.BoxGeometry(1.25, 0.09, 0.26);
        const barMat = new THREE.MeshBasicMaterial({ color: 0x34d399 });
        const barMesh = new THREE.Mesh(barGeo, barMat);
        barMesh.position.set(0, 1.1, 0.06);
        exGroup.add(barMesh);

        // Overhead Glowing "EXIT" Signboard
        const signTex = createExitSignCanvasTexture(ex.shortName);
        const signGeo = new THREE.PlaneGeometry(1.55, 0.58);
        const signMat = new THREE.MeshBasicMaterial({ map: signTex, side: THREE.DoubleSide });
        const signMesh = new THREE.Mesh(signGeo, signMat);
        signMesh.position.set(0, 3.05, 0.12);
        exGroup.add(signMesh);

        // Emerald Emergency PointLight casting green floor glow
        const exLight = new THREE.PointLight(0x10b981, 1.6, 8.5);
        exLight.position.set(0, 2.6, 0.9);
        exGroup.add(exLight);

        auditoriumGroup.add(exGroup);

        exitDoorsList.push({
            id: ex.id,
            name: ex.name,
            shortName: ex.shortName,
            side: ex.side,
            pos: new THREE.Vector3(ex.x, ex.y, ex.z),
            lookTarget: new THREE.Vector3(ex.x, ex.y + 1.6, ex.z)
        });
    });

    auditoriumGroup.children.slice(inspectionStart).forEach(object=>{object.userData.inspectionOccluder=true;});
    // 4. BUILD STADIUM RISERS & 3D SEATING GRID
    // Soft, bevelled upholstery panels keep the seat silhouette clean
    // at both overview distance and close seat POV.
    const upholsteryGeo = CinewaveChairGeometry.padding(THREE);
    const seatBackGeo = CinewaveChairGeometry.backrest(THREE);
    // Instanced batches keep seat upholstery, backs, armrests, frames,
    // and cup holders efficient for the largest saved layouts.
    // Instance colors preserve availability, class and cart states.
    const seatCapacity = config.rowDefs.reduce((sum, row) => {
        const start = Number(row.start || 1);
        const count = Number(row.count || 0);
        const blocked = new Set(row.blocked || []);
        let blockedInRow = 0;
        for (let n = start; n < start + count; n++) if (blocked.has(`${row.label}${n}`)) blockedInRow++;
        return sum + Math.max(0, count - blockedInRow);
    }, 0);
    const leatherLike = /leather|vinyl/i.test(String(seatProfile.upholstery || ''));
    const upholsteryMaterials = [matStdAvail, matVipAvail, matReclinerAvail].map(tint => new THREE.MeshStandardMaterial({
        color: 0xffffff, map: leatherLike ? null : seatFabricTexture,
        roughness: leatherLike ? 0.58 : tint.roughness, metalness: 0.01
    }));
    const categoryIndex = row => CinewaveSeatState.classifySeat(row);
    const categoryCapacity = [0, 0, 0];
    config.rowDefs.forEach(row => {
        categoryCapacity[categoryIndex(row)] += Object.keys(row.seats).length;
    });
    const armGeometry = CinewaveChairGeometry.armrest(THREE);
    const seatLegGeometry = new THREE.BoxGeometry(1, 1, 1);
    const seatLegMaterial = new THREE.MeshStandardMaterial({ color: 0x15171c, roughness: 0.58, metalness: 0.42 });
    // One shared, closed-section molded well: inner bowl, rounded lip,
    // outer wall and underside. Fewer triangles than the former torus.
    const cupHolderGeometry = CinewaveChairGeometry.cupHolder(THREE);
    const cupHolderMaterial = new THREE.MeshStandardMaterial({ color: 0x30343c, roughness: 0.44, metalness: 0.32 });
    const stitchGeometry = new THREE.BoxGeometry(1, 1, 1);
    // Three shared class materials, rather than one material per chair.
    const upholsteryBatches = upholsteryMaterials.map((material, index) => ({
        cushionInstances: new THREE.InstancedMesh(upholsteryGeo, material, Math.max(1, categoryCapacity[index] * 7)),
        backInstances: new THREE.InstancedMesh(seatBackGeo, material, Math.max(1, categoryCapacity[index] * 2))
    }));
    upholsteryBatches.forEach(batch => {
        batch.cushionInstances.userData.partKind = 'cushion';
        batch.backInstances.userData.partKind = 'back';
        // r128 allocates instanceColor from mesh.count on its first
        // setColorAt(). Allocate at full capacity BEFORE reducing the
        // draw count; otherwise only the first chair gets a colour.
        [batch.cushionInstances, batch.backInstances].forEach(mesh =>
            mesh.setColorAt(0, new THREE.Color(0xffffff)));
    });
    const armMaterial = matArmrest.clone();
    armMaterial.color.set(0xffffff);
    const armInstances = new THREE.InstancedMesh(armGeometry, armMaterial, Math.max(1, seatCapacity * 2));
    const legInstances = new THREE.InstancedMesh(seatLegGeometry, seatLegMaterial, Math.max(1, seatCapacity * 3));
    const cupHolderInstances = new THREE.InstancedMesh(cupHolderGeometry, cupHolderMaterial, Math.max(1, seatCapacity * 2));
    [armInstances, legInstances, cupHolderInstances].forEach(mesh => {
        mesh.userData.baseColor = mesh === armInstances ? matArmrest.color.clone() : mesh.material.color.clone();
        mesh.material.color.set(0xffffff);
        mesh.setColorAt(0, mesh.userData.baseColor);
    });
    // Seams and state bands share geometry and one colour-instanced
    // batch. State highlighting adds no draw call to the auditorium.
    const stitchInstances = new THREE.InstancedMesh(stitchGeometry,
        new THREE.MeshStandardMaterial({color: 0xffffff, roughness: 0.72, metalness: 0.08}), Math.max(1, seatCapacity * 6));
    stitchInstances.setColorAt(0, matSeatStitch.color);
    const stateInstances = stitchInstances;
    [armInstances, legInstances, cupHolderInstances, stitchInstances].forEach((mesh, index) => {
        mesh.userData.partKind = ['armrest', 'support', 'cup-holder', 'stitch'][index];
    });
    seatInstanceMeshes = [...upholsteryBatches.flatMap(batch => [batch.cushionInstances, batch.backInstances]),
        armInstances, legInstances, cupHolderInstances, stitchInstances];
    seatInstanceMeshes.forEach(mesh => {
        mesh.count = 0;
        mesh.userData.instanceSeatIds = [];
    });
    auditoriumGroup.add(...seatInstanceMeshes);
    const distantPadding=CinewaveChairGeometry.padding(THREE,'far');
    const distantBack=CinewaveChairGeometry.backrest(THREE,'far');
    seatGeometryVariants = upholsteryBatches.flatMap(batch=>[
        {mesh:batch.cushionInstances,near:upholsteryGeo,far:distantPadding},
        {mesh:batch.backInstances,near:seatBackGeo,far:distantBack}
    ]).concat([
        {mesh:armInstances,near:armGeometry,far:CinewaveChairGeometry.armrest(THREE,'far')},
        {mesh:cupHolderInstances,near:cupHolderGeometry,far:CinewaveChairGeometry.cupHolder(THREE,'far')}
    ]);
    interactiveSeatMeshes.push(...upholsteryBatches.flatMap(batch => [batch.cushionInstances, batch.backInstances]));

    const riserGeometry = new THREE.BoxGeometry(hallHalfWidth * 1.92, 1, 1);
    const riserMaterials = [
        new THREE.MeshStandardMaterial({ color: 0x0c1018, roughness: 0.86 }),
        new THREE.MeshStandardMaterial({ color: 0x131724, roughness: 0.84 }),
        new THREE.MeshStandardMaterial({ color: 0x16121e, roughness: 0.82 })
    ];
    const riserInstances = riserMaterials.map(material => {
        const mesh = new THREE.InstancedMesh(riserGeometry, material, Math.max(1, config.rowDefs.length));
        mesh.count = 0;
        mesh.userData.inspectionOccluder = true;
        auditoriumGroup.add(mesh);
        return mesh;
    });
    const riserCounts = [0, 0, 0];

    const aisleMarkerCapacity = Math.max(1, config.rowDefs.reduce((sum, row) => sum + (row.aislesAfter || []).length, 0));
    const aisleMarkerGeometry = new THREE.BoxGeometry(1, 1, 1);
    const aisleMarkerMaterial = new THREE.MeshStandardMaterial({
        color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 0.1,
        roughness: 0.62, metalness: 0.02
    });
    const aisleMarkerInstances = new THREE.InstancedMesh(aisleMarkerGeometry, aisleMarkerMaterial, aisleMarkerCapacity);
    aisleMarkerInstances.setColorAt(0, new THREE.Color(0xffffff));
    aisleMarkerInstances.count = 0;
    auditoriumGroup.add(aisleMarkerInstances);
    registerArchitecturalAccent(aisleMarkerMaterial, 'aisle');
    const aisleMarkerMatrix = new THREE.Object3D();
    let aisleMarkerIndex = 0;
    function writeSeatPart(seat, part) {
        const child = new THREE.Object3D();
        child.position.copy(part.position);
        child.rotation.x = part.rotationX || 0;
        child.scale.copy(part.scale);
        child.updateMatrix();
        const matrix = seat.group.matrix.clone().multiply(child.matrix);
        part.mesh.setMatrixAt(part.index, matrix);
        part.mesh.instanceMatrix.needsUpdate = true;
        part.mesh.userData.instanceSeatIds[part.index] = seat.id;
    }

    let seatInstanceIndex = 0;
    const upholsteryIndices = Array.from({length:3}, () => ({cushion:0, back:0}));
    let stitchCursor = 0;
    rows.forEach((rowLetter, rIdx) => {
        const rowConfig = config.rowDefs[rIdx];
        if (!rowConfig) return;
        const rowPhysical = rowPositions[rIdx] || { z: 7 + rIdx * rowSpacing, y: rIdx * stadiumSlope, riserHeight: stadiumSlope };
        const rowZ = Number(rowPhysical.z);
        const rowY = Number(rowPhysical.y);
        const category = categoryIndex(rowConfig);
        const isVIP = category === 1;
        const isRecliner = category === 2;
        const {cushionInstances, backInstances} = upholsteryBatches[category];
        const rowSpan = Math.max(1, rowConfig.seatSpan || 1);
        const aisles = rowConfig.aislesAfter || [];

        const riserHeight = Math.max(0.08, Number(rowPhysical.riserHeight || stadiumSlope));
        const riserIndex = isRecliner ? 2 : (isVIP ? 1 : 0);
        const riserMesh = riserInstances[riserIndex];
        const riserMatrix = new THREE.Object3D();
        riserMatrix.position.set(0, Math.max(0, rowY - riserHeight / 2), rowZ);
        riserMatrix.scale.set(1, riserHeight, Number(rowPhysical.rowSpacing || rowSpacing));
        riserMatrix.updateMatrix();
        riserMesh.setMatrixAt(riserCounts[riserIndex], riserMatrix.matrix);
        riserCounts[riserIndex]++;
        riserMesh.count = riserCounts[riserIndex];

        const firstSeat = Number(rowConfig.start || 1);
        const rowWidthM = rowConfig.count * rowSpan * 0.62 + aisles.length * 0.85 + Number(rowConfig.offset || 0) * 0.62;
        for (let sNum = firstSeat; sNum < firstSeat + rowConfig.count; sNum++) {
            const seatId = `${rowLetter}${sNum}`;
            if ((rowConfig.blocked || []).includes(seatId)) continue;
            const seatIndex = sNum - firstSeat;
            const aislesBefore = aisles.filter(aisle => sNum > aisle).length;
            const seatX = seatIndex * rowSpan * 0.62 + rowSpan * 0.31 + aislesBefore * 0.85
                + Number(rowConfig.offset || 0) * 0.62 - rowWidthM / 2;
            const isOccupied = rowConfig.seats[seatId] !== 'available';
            const tier = rowConfig.className || 'Standard';
            const price = Number(rowConfig.price || 0);

            const seatGroup = new THREE.Group();
            seatGroup.position.set(seatX, rowY, rowZ);
            if (isRecliner || isVIP || rowSpan > 1) {
                // rowSpan is represented by seatWidth below; applying
                // it here too made couple seats grow by span squared.
                const widthScale = isRecliner ? 1.06 : (isVIP ? 1.04 : 1);
                seatGroup.scale.set(widthScale, isRecliner ? 0.72 : (isVIP ? 0.69 : 0.67), isRecliner || isVIP ? 1 : 0.82);
            } else {
                seatGroup.scale.set(1, 0.67, 0.82);
            }
            // The seat back is local +Z; the screen is at -Z. Aim the
            // seat fronts toward the screen and keep the active seat
            // back behind the seated camera instead of in its sightline.
            // Strongly fanning edge chairs toward screen centre made
            // arms overlap the next chair. Keep rows nearly parallel,
            // and aisle-edge/reclining chairs parallel to the aisle.
            seatGroup.rotation.y = isRecliner || aisles.includes(sNum) || aisles.includes(sNum-1)
                ? 0 : THREE.MathUtils.clamp(Math.atan2(seatX,rowZ-screenSurfaceZ),-0.06,0.06);

            seatGroup.updateMatrix();
            seatGroup.updateMatrixWorld(true);
            const part = (mesh, index, position, scale, rotationX = 0, kind = '') => ({
                mesh, index, position: new THREE.Vector3(...position),
        scale: new THREE.Vector3(...scale), rotationX, kind
            });
            const base = seatInstanceIndex++;
            const backIndex = upholsteryIndices[category].back;
            const upholsteryStart = upholsteryIndices[category].cushion;
            upholsteryIndices[category].back += rowSpan > 1 ? 2 : 1;
            const padsPerPosition = isVIP || isRecliner ? 3 : 2;
            upholsteryIndices[category].cushion += (rowSpan > 1 ? 2 : 1) * padsPerPosition + (isRecliner ? 1 : 0);
            const armStart = base * 2;
            const supportStart = base * 3;
            const cupStart = base * 2;
            const reclineTilt = isRecliner && seatId === activePOVSeatId
                ? THREE.MathUtils.degToRad([8,25,45][reclineLevel]) : 0.14;
            const isWide = rowSpan > 1;
            const stitchStart = stitchCursor;
            stitchCursor += isWide ? 6 : 4;
            const seatWidth = rowSpan * (isRecliner ? 0.46 : (isVIP ? 0.48 : 0.46));
            const seatHeight = isRecliner ? 0.78 : (isVIP ? 0.73 : 0.67);
            const seatDepth = isRecliner ? 1.12 : (isVIP ? 1.06 : 0.82);
            const seat = {
                id: seatId, row: rowLetter, rowIndex: rIdx, num: sNum,
                isOccupied, isVIP, isRecliner, tier, price, status: rowConfig.seats[seatId],
                worldPos: seatGroup.position.clone(),
                // Keep a consistent adult seated eye height (~1.16 m
                // above the row base) across standard and recliner
                // seat scales, clearing the next row's headrest.
                // Keep the viewpoint above the seat pan and slightly
                // forward of the backrest, without placing it in the
                // next row's seating envelope.
                eyePos: seatGroup.localToWorld(new THREE.Vector3(0, 1.16 / seatGroup.scale.y, -0.24)),
                group: seatGroup,
                instanceParts: [
                    ...Array.from({length:isWide?2:1}, (_,side) => {
                        const width=isWide?seatWidth*0.48:seatWidth;
                        const x=isWide?(side===0?-1:1)*seatWidth*0.25:0;
                        return [
                            part(cushionInstances, upholsteryStart+side*padsPerPosition, [x,0.48,-0.04], [width*0.48,isVIP||isRecliner?0.17:0.13,seatDepth*0.40],0,'cushion'),
                            part(cushionInstances, upholsteryStart+side*padsPerPosition+1, [x,1.28,0.30], [width*0.36,isVIP||isRecliner?0.13:0.11,0.065],0,'headrest'),
                            part(backInstances,backIndex+side,[x,0.48,0.22],[width,isVIP||isRecliner?seatHeight*1.15:seatHeight,seatDepth],reclineTilt,'back'),
                            ...(padsPerPosition === 3 ? [part(cushionInstances, upholsteryStart+side*padsPerPosition+2,
                                [x,0.75,0.17],[width*0.43,0.085,0.045],reclineTilt,'lumbar')] : [])
                        ];
                    }).flat(),
                    ...(isRecliner ? [part(cushionInstances,upholsteryStart+(isWide?2:1)*padsPerPosition,[0,0.28,-0.62],[seatWidth*0.44,0.10,0.23],0,'footrest')] : []),
                    part(armInstances, armStart, [-0.48 * seatWidth, isRecliner ? 0.66 : 0.65, 0.035], [(isWide?0.065:0.115) * seatWidth, (isVIP||isRecliner?0.17:0.13) * seatHeight, 0.43 * seatDepth]),
                    part(armInstances, armStart + 1, [0.48 * seatWidth, isRecliner ? 0.66 : 0.65, 0.035], [(isWide?0.065:0.115) * seatWidth, (isVIP||isRecliner?0.17:0.13) * seatHeight, 0.43 * seatDepth]),
                    part(legInstances, supportStart, [-0.32 * seatWidth, 0.17, 0.1], [0.065, 0.34, 0.08]),
                    part(legInstances, supportStart + 1, [0.32 * seatWidth, 0.17, 0.1], [0.065, 0.34, 0.08]),
                    part(legInstances, supportStart + 2, [0, 0.08, 0.02], [0.68 * seatWidth, 0.055, 0.075]),
                    ...(seatProfile.cup_holder === false ? [] : [
                        part(cupHolderInstances, cupStart, [-0.48 * seatWidth, isRecliner ? 0.79 : (isVIP ? 0.78 : 0.74), 0.035-0.42*0.95*0.43*seatDepth], [(isWide?0.065:0.115)*seatWidth*0.82/0.043,1,0.95*0.43*seatDepth*0.112/0.043]),
                        part(cupHolderInstances, cupStart + 1, [0.48 * seatWidth, isRecliner ? 0.79 : (isVIP ? 0.78 : 0.74), 0.035-0.42*0.95*0.43*seatDepth], [(isWide?0.065:0.115)*seatWidth*0.82/0.043,1,0.95*0.43*seatDepth*0.112/0.043])
                    ]),
                    ...Array.from({length:isWide?2:1},(_,side)=>{
                        const x=isWide?(side===0?-1:1)*seatWidth*0.25:0;
                        const width=isWide?seatWidth*0.48:seatWidth;
                        return [
                            part(stitchInstances,stitchStart+side*2,[x,0.43,-0.38],[0.42*width,0.006,0.006],0,'pan-seam'),
                            part(stitchInstances,stitchStart+side*2+1,[x,1.34,0.34],[0.40*width,0.005,0.005],0,'head-seam')
                        ];
                    }).flat(),
                    part(stateInstances, stitchStart+(isWide?4:2), [0,0.47,-0.04-seatDepth*0.402], [seatWidth*0.72,0.035,0.012],0,'state-front'),
                    part(stateInstances, stitchStart+(isWide?5:3), [0,1.0,0.44], [seatWidth*0.66,0.035,0.012],reclineTilt,'state-back')
                ],
                meshes: [],
                updateTransforms() {
                    this.group.updateMatrix();
                    this.instanceParts.forEach(item => writeSeatPart(this, item));
                }
            };
            const componentCounts = new Map();
            seat.componentIndices = {};
            seat.instanceParts.forEach(item => {
                const kind = item.kind || item.mesh.userData.partKind;
                const number = (componentCounts.get(kind) || 0) + 1;
                componentCounts.set(kind, number);
                item.componentName = `${kind}-${number}`;
                seat.componentIndices[item.componentName] = {batch: seatInstanceMeshes.indexOf(item.mesh), index: item.index};
                if (item.mesh.userData.baseColor) item.mesh.setColorAt(item.index,item.mesh.userData.baseColor);
            });
            seat.meshes = seat.instanceParts.filter(item => item.mesh===cushionInstances || item.mesh===backInstances);
            seat.instanceParts.forEach(item => {
                item.mesh.count = Math.max(item.mesh.count, item.index + 1);
                if (item.mesh === stitchInstances) item.mesh.setColorAt(item.index,
                    item.kind.startsWith('state-') ? seatMarkerColors.available : matSeatStitch.color);
                writeSeatPart(seat, item);
            });
            seat.meshes.forEach(ref => { ref.mesh.userData.instanceSeatIds[ref.index] = seatId; });
            seatRegistry.set(seatId, seat);
            const initialColor = isOccupied ? matOccupied.color : (isRecliner ? matReclinerAvail.color : (isVIP ? matVipAvail.color : matStdAvail.color));
            seat.meshes.forEach(ref => ref.mesh.setColorAt(ref.index, initialColor));

            if (aisles.includes(sNum)) {
                aisleMarkerMatrix.position.set(seatX + rowSpan * 0.6 + 0.4, rowY + 0.02, rowZ);
                aisleMarkerMatrix.scale.set(0.14, 0.04, 2.3);
                aisleMarkerMatrix.updateMatrix();
                aisleMarkerInstances.setMatrixAt(aisleMarkerIndex, aisleMarkerMatrix.matrix);
                aisleMarkerInstances.setColorAt(aisleMarkerIndex, isVIP || isRecliner
                    ? new THREE.Color('#c9a84c') : new THREE.Color('#43a9a0'));
                aisleMarkerIndex++;
                aisleMarkerInstances.count = aisleMarkerIndex;
            }

            // Put the camera at seated eye height on the seat's front
            // side. The local -Z direction faces the screen; transforming
            // it through the seat group also handles side-row rotation.
        }
    });
    [...seatInstanceMeshes, ...riserInstances, aisleMarkerInstances].forEach(mesh => {
        if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
        mesh.instanceMatrix.needsUpdate = true;
    });
    auditoriumBuildDurationMs = performance.now() - buildStartedAt;
    applyArchitecturalLightingMode();
    updateSeatDetailForView();
    populateInspectionLevels();
}

window.cinewavePreviewMetrics = () => ({
    sceneBuildMs: Number(auditoriumBuildDurationMs.toFixed(1)),
    sceneUsableMs: previewUsableAt ? Number((previewUsableAt - previewStartedAt).toFixed(1)) : null,
    averageFps: Number(measuredFps.toFixed(1)),
    drawCalls: renderer.info.render.calls,
    triangles: renderer.info.render.triangles,
    renderedSeats: seatRegistry.size,
    geometries: renderer.info.memory.geometries,
    textures: renderer.info.memory.textures,
    renderQuality,
    chairDetail,
    inspection: cameraMode === 'inspection',
    devicePixelRatio: renderer.getPixelRatio()
});
window.cinewavePreviewDiagnostics = () => {
    const canvas = renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    const gl = renderer.getContext();
    return {
        threeRevision: THREE.REVISION,
        rendererInitialized: !!renderer && canvas.isConnected,
        webglAvailable: !!gl,
        webglContextLost: gl.isContextLost(),
        canvas: {
            cssWidth: Math.round(rect.width), cssHeight: Math.round(rect.height),
            bufferWidth: canvas.width, bufferHeight: canvas.height,
            visible: getComputedStyle(canvas).visibility !== 'hidden'
        },
        sceneObjects: scene.children.length,
        auditoriumObjects: auditoriumGroup.children.length,
        cameraPosition: camera.position.toArray().map(value => Number(value.toFixed(2))),
        cameraTarget: currentLookAtTarget.toArray().map(value => Number(value.toFixed(2))),
        fallbackActive: document.body.classList.contains('webgl-fallback'),
        fallbackMessage: document.getElementById('fallback-explanation')?.textContent || '',
        metrics: window.cinewavePreviewMetrics()
    };
};
// Read-only mapping hook used by browser regression checks to ensure
// 2D seat IDs, raycast instance IDs and stored transforms stay aligned.
window.cinewavePreviewSeatMapping = seatId => {
    const seat = seatRegistry.get(String(seatId));
    const result = CinewaveSeatState.inspectMapping(seatId, seatRegistry, seatInstanceMeshes, currentAudi.rowDefs);
    if (!seat) return result;
    result.worldPosition = seat.worldPos.toArray().map(value => Number(value.toFixed(3)));
    result.instances.forEach(instance => {
        if (instance.batch < 0 || instance.index < 0 || instance.index >= seatInstanceMeshes[instance.batch].count) return;
        const matrix = new THREE.Matrix4();
        seatInstanceMeshes[instance.batch].getMatrixAt(instance.index, matrix);
        instance.position = new THREE.Vector3().setFromMatrixPosition(matrix).toArray()
            .map(value => Number(value.toFixed(3)));
    });
    return result;
};
function refreshAllSeatMaterials() {
    seatRegistry.forEach((seat) => {
        const categoryColor = seat.isRecliner ? matReclinerAvail.color : (seat.isVIP ? matVipAvail.color : matStdAvail.color);
        const state = seat.isOccupied ? seat.status : (selectedSeats.has(seat.id) ? 'selected' : (seat.id === activePOVSeatId ? 'active' : 'available'));
        // Keep the actual fabric hue; booking state has its own narrow
        // front/rear bands rather than replacing the entire chair.
        const targetColor = categoryColor.clone();
        if (seat.isOccupied) targetColor.lerp(matOccupied.color, 0.65);
        else if (state === 'selected') targetColor.lerp(matSelectedCart.color, 0.16);
        else if (state === 'active') targetColor.lerp(matActivePOV.color, 0.14);
        seat.meshes.forEach(ref => ref.mesh.setColorAt(ref.index, targetColor));
        seat.instanceParts.filter(item => item.kind.startsWith('state-'))
            .forEach(item => item.mesh.setColorAt(item.index, seatMarkerColors[state] || seatMarkerColors.unavailable));
        seat.instanceParts.filter(item => item.mesh.userData.baseColor).forEach(item => {
            const color = item.mesh.userData.baseColor.clone();
            if (state === 'selected' || state === 'active') color.lerp(seatMarkerColors[state],0.45);
            item.mesh.setColorAt(item.index,color);
        });
        const level = seat.isRecliner && seat.id===activePOVSeatId ? reclineLevel : 0;
        // +X rotation moves the back toward local +Z, away from the
        // screen. Use that same hinge for the headrest and lumbar pad.
        // Compensate nonuniform group scale: 45 degrees must be 45
        // in the auditorium, rather than a more horizontal 57 degrees.
        const angle = seat.isRecliner ? Math.atan(Math.tan(THREE.MathUtils.degToRad([8,25,45][level]))
            *seat.group.scale.y/seat.group.scale.z) : 0.14;
        if (seat.transformLevel === level) return;
        seat.transformLevel = level;
        const height = (seat.isRecliner ? 0.78*1.15 : (seat.isVIP ? 0.73*1.15 : 0.67))*1.05;
        const pivotZ = 0.22 - level*0.21;
        const attach = (item, distance, depth) => {
            item.position.y = 0.48 + distance*Math.cos(angle) - depth*Math.sin(angle);
            item.position.z = pivotZ + distance*Math.sin(angle) + depth*Math.cos(angle);
            item.rotationX = angle;
        };
        seat.instanceParts.forEach(item => {
            if(item.kind==='back') { item.rotationX=angle; item.position.z=pivotZ; }
            if(item.kind==='headrest') attach(item,height,0.02);
            if(item.kind==='head-seam') attach(item,height-0.025,-0.048);
            if(item.kind==='lumbar') attach(item,0.27,-0.025);
            if(item.kind==='state-back') attach(item,0.54,seat.isRecliner?0.25:(seat.isVIP?0.24:0.19));
            if(item.kind==='footrest') {
                item.position.y=0.28+level*0.10;
                item.position.z=-0.36-level*0.05;
                item.scale.z=0.18;
                item.rotationX=level*0.10;
            }
        });

        seat.updateTransforms();
    });
    seatInstanceMeshes.forEach(mesh => { if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true; });
}

/********************************************************************
 * 5. 3D ANIMATED GREEN FLOOR EGRESS PATH TO NEAREST EXIT WAY
 ********************************************************************/
function updateNearestExitWayAndFloorPath(seat) {
    if (!seat || exitDoorsList.length === 0) return;

    let minDist = Infinity;
    let bestExit = exitDoorsList[0];

    exitDoorsList.forEach(ex => {
        const d = seat.worldPos.distanceTo(ex.pos);
        if (d < minDist) {
            minDist = d;
            bestExit = ex;
        }
    });

    nearestExitObj = { exit: bestExit, dist: minDist.toFixed(1) };

    // Remove old egress line & nodes
    if (egressLineMesh) {
        scene.remove(egressLineMesh);
        egressLineMesh.geometry.dispose();
    }
    while (egressNodes.length > 0) {
        const n = egressNodes.pop();
        scene.remove(n);
    }

    // Build 3-point walking route: Seat Feet -> Side Wall Corridor -> Nearest Exit Door
    const corridorX = bestExit.pos.x * 0.88;
    const p1 = new THREE.Vector3(seat.worldPos.x, seat.worldPos.y + 0.08, seat.worldPos.z + 0.55);
    const p2 = new THREE.Vector3(corridorX, seat.worldPos.y + 0.08, seat.worldPos.z + 0.55);
    const p3 = new THREE.Vector3(bestExit.pos.x * 0.94, bestExit.pos.y + 0.15, bestExit.pos.z);

    const lineGeo = new THREE.BufferGeometry().setFromPoints([p1, p2, p3]);
    const lineMat = new THREE.LineBasicMaterial({ color: 0x10b981, linewidth: 3 });
    egressLineMesh = new THREE.Line(lineGeo, lineMat);
    scene.add(egressLineMesh);

    // Add glowing green beacon spheres along the walking route
    const nodeGeo = new THREE.SphereGeometry(0.11, 12, 12);
    const nodeMat = new THREE.MeshBasicMaterial({ color: 0x34d399 });
    for (let i = 0; i <= 8; i++) {
        const t = i / 8;
        const pt = t < 0.45
            ? new THREE.Vector3().lerpVectors(p1, p2, t / 0.45)
            : new THREE.Vector3().lerpVectors(p2, p3, (t - 0.45) / 0.55);
        const sphere = new THREE.Mesh(nodeGeo, nodeMat);
        sphere.position.copy(pt);
        sphere.userData = { phase: i * 0.6 };
        scene.add(sphere);
        egressNodes.push(sphere);
    }
}

/********************************************************************
 * 6. 2D INTERACTIVE RADAR MINI-MAP RENDERER
 ********************************************************************/
function render2DMinimap() {
    const gridEl = document.getElementById('minimap-grid');
    gridEl.replaceChildren();
    currentAudi.rowDefs.forEach(row => {
        const rowWrap = document.createElement('div');
        rowWrap.className = 'flex items-center justify-between gap-1';
        const labelL = document.createElement('span');
        labelL.className = 'w-5 shrink-0 text-[9px] font-display font-bold text-slate-400 text-center';
        labelL.textContent = row.label;
        rowWrap.appendChild(labelL);
        const seatsRow = document.createElement('div');
        seatsRow.className = 'flex items-center justify-center gap-[3px] flex-1';
        for (let sNum = row.start; sNum < row.start + row.count; sNum++) {
            const seatId = `${row.label}${sNum}`;
            if (row.blocked.includes(seatId)) continue;
            const seatData = seatRegistry.get(seatId);
            if (!seatData) continue;
            const seatButton = document.createElement('button');
            seatButton.type = 'button';
            seatButton.title = `${seatData.isOccupied ? seatData.status + ' · ' : ''}Row ${row.label} Seat ${sNum} (${seatData.tier} · ₹${seatData.price})`;
            let colorClasses = 'bg-rose-900/75 border-rose-500/60 text-rose-100 hover:border-rose-200';
            if (seatData.status === 'held') colorClasses = 'occupied bg-amber-950 border-amber-500 text-amber-200 cursor-not-allowed';
            else if (seatData.status === 'booked') colorClasses = 'occupied bg-rose-950 border-rose-500 text-rose-200 cursor-not-allowed';
            else if (seatData.isOccupied) colorClasses = 'occupied bg-slate-800 border-slate-600 text-slate-500 cursor-not-allowed';
            else if (selectedSeats.has(seatId)) colorClasses = 'bg-[#E4C67F] border-[#F2DFAE] text-slate-950 font-bold shadow-[0_0_9px_rgba(228,198,127,.5)]';
            else if (seatId === activePOVSeatId) colorClasses = 'bg-[#91CFC1] border-white text-slate-950 font-black shadow-[0_0_9px_rgba(145,207,193,.45)] scale-125 z-10';
            else if (seatData.isRecliner) colorClasses = 'bg-emerald-900/80 border-emerald-500/70 text-emerald-100';
            else if (seatData.isVIP) colorClasses = 'bg-[#98794E] border-[#D2B77E] text-white';
            seatButton.className = `seat-dot h-4 w-4 rounded-t-md rounded-b-sm border text-[7px] flex items-center justify-center ${colorClasses}`;
            seatButton.textContent = sNum;
            if (!seatData.isOccupied) seatButton.onclick = () => selectAndFlyToSeat(row.label, sNum, true);
            seatsRow.appendChild(seatButton);
            if (row.aislesAfter.includes(sNum)) {
                const spacer = document.createElement('div');
                spacer.className = 'w-2 shrink-0';
                seatsRow.appendChild(spacer);
            }
        }
        rowWrap.appendChild(seatsRow);
        const labelR = document.createElement('span');
        labelR.className = 'w-5 shrink-0 text-[9px] font-display font-bold text-slate-400 text-center';
        labelR.textContent = row.label;
        rowWrap.appendChild(labelR);
        gridEl.appendChild(rowWrap);
    });
}
/********************************************************************
 * 7. SEAT POV CAMERA NAVIGATION, 4-WAY ARROWS & EXIT WAY LOOK
 ********************************************************************/
const cameraTargetPos = new THREE.Vector3();

let yawOffset = 0;
let pitchOffset = 0;
let targetYawOffset = 0;
let targetPitchOffset = 0;

function selectAndFlyToSeat(rowLetter, seatNum, addToCart = false) {
    const seatId = `${rowLetter}${seatNum}`;
    const seat = seatRegistry.get(seatId);
    if (!seat) return;

    if (addToCart) {
        if (seat.isOccupied) return;
        window.parent.postMessage({ type: 'cinewave:toggle-seat', seatId }, location.origin);
    }

    activePOVSeatId = seatId;
    activeRowIdx = seat.rowIndex;
    activeColNum = seat.num;

    cameraMode = 'seat';
    updateCameraModeButtons();
    cameraTargetPos.copy(seat.eyePos);

    // Derive the sightline from this seat's world-space eye point to
    // the actual screen centre so corner seats retain their angle.
    desiredLookAtTarget.copy(screenCenterTarget);
    targetYawOffset = 0;
    targetPitchOffset = reclineLevel * 0.12;

    // Stop any pending hover preview so the committed seat is unambiguous.
    hideHoverPreview();
    if (seat.group) seat.group.userData.hoverElevation = 0;

    updateArrowButtonStates();
    updateNearestExitWayAndFloorPath(seat);
    refreshAllSeatMaterials();
    render2DMinimap();
    updateSeatTelemetryUI(seat);
}

// 4-Way Directional Seat-Hopping (◀ Left, ▶ Right, ▲ Front Row, ▼ Back Row)
function stepSeat(dRow, dCol) {
    if (dCol !== 0) {
        const row = currentAudi.rowDefs[activeRowIdx];
        if (!row) return;
        let nextCol = activeColNum + dCol;
        while (nextCol >= row.start && nextCol < row.start + row.count) {
            if (seatRegistry.has(`${row.label}${nextCol}`)) {
                selectAndFlyToSeat(row.label, nextCol, false);
                return;
            }
            nextCol += dCol;
        }
        return;
    }

    const nextRIdx = activeRowIdx + dRow;
    if (nextRIdx < 0 || nextRIdx >= currentAudi.rowDefs.length) return;
    const targetRow = currentAudi.rowDefs[nextRIdx];
    const rowSeats = [...seatRegistry.values()].filter(seat => seat.rowIndex === nextRIdx);
    if (!rowSeats.length) return;
    const nextSeat = rowSeats.reduce((best, seat) =>
        Math.abs(seat.num - activeColNum) < Math.abs(best.num - activeColNum) ? seat : best
    );
    selectAndFlyToSeat(targetRow.label, nextSeat.num, false);
}

function updateArrowButtonStates() {
    document.getElementById('btn-row-front').disabled = (activeRowIdx >= currentAudi.rowDefs.length - 1);
    document.getElementById('btn-row-back').disabled = (activeRowIdx <= 0);
    const row = currentAudi.rowDefs[activeRowIdx];
    document.getElementById('btn-seat-left').disabled = !row || activeColNum <= row.start;
    document.getElementById('btn-seat-right').disabled = !row || activeColNum >= row.start + row.count - 1;
}

function lookAtNearestExit() {
    if (!nearestExitObj) return;
    cameraMode = 'seat';
    updateCameraModeButtons();
    desiredLookAtTarget.copy(nearestExitObj.exit.lookTarget);
    targetYawOffset = 0;
    targetPitchOffset = 0;

    const dockBtn = document.getElementById('btn-dock-exit');
    dockBtn.classList.add('emerald-active');
    setTimeout(() => dockBtn.classList.remove('emerald-active'), 2200);
}

function lookAtSpecificExit(exitId) {
    const found = exitDoorsList.find(e => e.id === exitId);
    if (!found) return;
    desiredLookAtTarget.copy(found.lookTarget);
    targetYawOffset = 0;
    targetPitchOffset = 0;
}

function recenterLookAtScreen() {
    desiredLookAtTarget.copy(screenCenterTarget);
    targetYawOffset = 0;
    targetPitchOffset = reclineLevel * 0.12;
}

function setSeatRecline(level) {
    reclineLevel = level;
    [0, 1, 2].forEach(l => {
        const b = document.getElementById(`recline-${l}`);
        if (b) b.classList.toggle('gold-active', l === level);
    });
    targetPitchOffset = level * 0.12;
    refreshAllSeatMaterials();
}

function jumpToSweetSpot() {
    const centerX = seatRegistry.size ? [...seatRegistry.values()].reduce((sum, seat) => sum + seat.worldPos.x, 0) / seatRegistry.size : 0;
    const centerRow = (currentAudi.rows.length - 1) * 0.48;
    const best = [...seatRegistry.values()].filter(seat => !seat.isOccupied).reduce((choice, seat) => {
        if (!choice) return seat;
        const score = Math.hypot(seat.worldPos.x - centerX, (seat.rowIndex - centerRow) * 2.5);
        const bestScore = Math.hypot(choice.worldPos.x - centerX, (choice.rowIndex - centerRow) * 2.5);
        return score < bestScore ? seat : choice;
    }, null);
    if (best) selectAndFlyToSeat(best.row, best.num, false);
}

function setCameraMode(mode) {
    cameraMode = mode;
    updateCameraModeButtons();
    if (mode === 'overview') {
        // Recompute the responsive eye and target before returning
        // from another mode or applying a new viewport aspect ratio.
        applyOverviewFieldOfView();
        cameraTargetPos.copy(auditoriumOverviewCamera);
        desiredLookAtTarget.copy(auditoriumOverviewTarget);
        targetYawOffset = 0;
        targetPitchOffset = 0;
    } else {
        setCameraFieldOfView(65);
        const seat = seatRegistry.get(activePOVSeatId);
        if (seat) cameraTargetPos.copy(seat.eyePos);
        desiredLookAtTarget.copy(screenCenterTarget);
        targetYawOffset = 0;
        targetPitchOffset = reclineLevel * 0.12;
    }
}

function applyBirdseyeFraming() {
    // Frame the actual seat envelope from the rear of the room, just
    // below the opaque ceiling. The rearward offset provides enough
    // perspective distance for wide seat blocks without a vertical
    // lookAt singularity or a camera outside the auditorium.
    const seats = [...seatRegistry.values()];
    const minX = seats.length ? Math.min(...seats.map(seat => seat.worldPos.x)) : -auditoriumHalfWidth * 0.6;
    const maxX = seats.length ? Math.max(...seats.map(seat => seat.worldPos.x)) : auditoriumHalfWidth * 0.6;
    const minZ = seats.length ? Math.min(...seats.map(seat => seat.worldPos.z)) : auditoriumCenterTarget.z - 4;
    const maxZ = seats.length ? Math.max(...seats.map(seat => seat.worldPos.z)) : auditoriumCenterTarget.z + 4;
    const minY = seats.length ? Math.min(...seats.map(seat => seat.worldPos.y)) : 0;
    const maxY = seats.length ? Math.max(...seats.map(seat => seat.worldPos.y)) + 1.1 : 1.1;
    const seatCenter = new THREE.Vector3((minX + maxX) * 0.5,
        Math.max(0.3, (minY + maxY) * 0.22), (minZ + maxZ) * 0.5);
    const framingMargin = Math.max(1.2, (maxX - minX) * 0.12);
    const frameAspect = Math.max(0.25, container.clientWidth / Math.max(1, container.clientHeight));
    const eyeHeight = Math.max(0.6,
        Math.min(auditoriumRoomHeight - 0.4, auditoriumRoomHeight * 0.9));
    const rearAisleZ = Math.max(maxZ + 3.5, auditoriumRearWallZ - 0.65);
    const candidatePosition = new THREE.Vector3(seatCenter.x + 0.14, eyeHeight, rearAisleZ);
    const forward = seatCenter.clone().sub(candidatePosition).normalize();
    const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
    const up = new THREE.Vector3().crossVectors(right, forward).normalize();
    let horizontalSlope = 0;
    let verticalSlope = 0;
    [minX - framingMargin, maxX + framingMargin].forEach(x => {
        [minY - 0.15, maxY + 0.15].forEach(y => {
            [minZ - framingMargin * 0.5, maxZ + framingMargin * 0.5].forEach(z => {
                const relative = new THREE.Vector3(x, y, z).sub(candidatePosition);
                const depth = relative.dot(forward);
                if (depth <= 0.25) return;
                horizontalSlope = Math.max(horizontalSlope, Math.abs(relative.dot(right)) / depth);
                verticalSlope = Math.max(verticalSlope, Math.abs(relative.dot(up)) / depth);
            });
        });
    });
    const requiredSlope = Math.max(verticalSlope, horizontalSlope / frameAspect) * 1.08;
    const requiredFov = THREE.MathUtils.radToDeg(2 * Math.atan(requiredSlope));
    const birdseyeFov = THREE.MathUtils.clamp(Math.max(68, requiredFov), 68, 72);
    setCameraFieldOfView(birdseyeFov);
    cameraTargetPos.copy(candidatePosition);
    desiredLookAtTarget.copy(seatCenter);
}

function setCameraPreset(preset) {
    if (preset === 'inspection') {
        cameraMode='inspection';updateCameraModeButtons();frameInspectionLevel();return;
    }
    if (preset === 'overview') return setCameraMode('overview');
    if (preset === 'reset') return setCameraMode('overview');
    if (preset === 'seat') return setCameraMode('seat');
    if (preset === 'screen') {
        cameraMode = preset;
        updateCameraModeButtons();
        setCameraFieldOfView(60);
        cameraTargetPos.copy(auditoriumScreenCamera);
        desiredLookAtTarget.copy(screenCenterTarget);
        targetYawOffset = 0;
        targetPitchOffset = 0;
        return;
    }
    if (preset === 'left' || preset === 'right') {
        cameraMode = preset;
        updateCameraModeButtons();
        setCameraFieldOfView(58);
        cameraTargetPos.copy(preset === 'left' ? auditoriumLeftCamera : auditoriumRightCamera);
        desiredLookAtTarget.copy(screenCenterTarget);
        targetYawOffset = 0;
        targetPitchOffset = 0;
        return;
    }
    if (preset === 'balcony') {
        const balconyRows = (currentAudi.geometry?.rows || []).filter(row => ['balcony', 'mezzanine'].includes(String(row.levelType || '').toLowerCase()));
        if (!balconyRows.length) return setCameraMode('overview');
        const middle = balconyRows[Math.floor(balconyRows.length / 2)];
        cameraMode = preset;
        updateCameraModeButtons();
        setCameraFieldOfView(60);
        cameraTargetPos.set(0, Number(middle.y) + 2.2, Number(middle.z) + 3.5);
        desiredLookAtTarget.set(0, screenCenterTarget.y, screenCenterTarget.z);
        targetYawOffset = 0;
        targetPitchOffset = 0;
        return;
    }
    cameraMode = preset;
    updateCameraModeButtons();
    targetYawOffset = 0;
    targetPitchOffset = 0;
    if (preset === 'stage') {
        setCameraFieldOfView(60);
        cameraTargetPos.set(0, Math.max(2.8, screenCenterTarget.y * 0.42), screenCenterTarget.z + 4.5);
        desiredLookAtTarget.copy(auditoriumCenterTarget);
    } else if (preset === 'birdseye') {
        applyBirdseyeFraming();
    }
}

function updateSeatDetailForView() {
    const distant = ['overview','birdseye','inspection'].includes(cameraMode) && renderQuality !== 'high';
    chairDetail = distant ? 'far' : 'near';
    seatGeometryVariants.forEach(v=>{const geometry=distant?v.far:v.near;if(v.mesh.geometry!==geometry)v.mesh.geometry=geometry;});
}

function populateInspectionLevels() {
    const select=document.getElementById('inspection-level');
    select.replaceChildren(new Option('All levels','all'));
    const levels=new Map();
    currentAudi.rowDefs.forEach(row=>levels.set(row.level_id||'main',row.level_id||'main'));
    const names=new Map((currentAudi.geometry?.levels||[]).map(l=>[l.id,l.name||l.id]));
    levels.forEach((_,id)=>select.add(new Option(names.get(id)||id,id)));
}

function applyInspectionMode() {
    const active=cameraMode==='inspection';
    if(active!==inspectionActive){
        if(active){inspectionFog=scene.fog;inspectionFar=camera.far;scene.fog=null;}
        else {scene.fog=inspectionFog;camera.far=inspectionFar;camera.updateProjectionMatrix();}
        inspectionActive=active;
    }
    document.body.classList.toggle('seat-inspection',active);
    auditoriumGroup.children.forEach(object=>{
        if(!object.userData.inspectionOccluder)return;
        if(active){if(object.userData.inspectionVisible===undefined)object.userData.inspectionVisible=object.visible;object.visible=false;}
        else if(object.userData.inspectionVisible!==undefined){object.visible=object.userData.inspectionVisible;delete object.userData.inspectionVisible;}
    });
}

function frameInspectionLevel() {
    const level=document.getElementById('inspection-level').value;
    const seats=[...seatRegistry.values()].filter(seat=>level==='all'||(currentAudi.rowDefs[seat.rowIndex].level_id||'main')===level);
    if(!seats.length)return;
    const min=new THREE.Vector3(Math.min(...seats.map(s=>s.worldPos.x))-0.7,Math.min(...seats.map(s=>s.worldPos.y)),Math.min(...seats.map(s=>s.worldPos.z))-0.8);
    const max=new THREE.Vector3(Math.max(...seats.map(s=>s.worldPos.x))+0.7,Math.max(...seats.map(s=>s.worldPos.y))+1.25,Math.max(...seats.map(s=>s.worldPos.z))+0.8);
    const center=min.clone().add(max).multiplyScalar(0.5),direction=new THREE.Vector3(0.65,0.9,1).normalize();
    const forward=direction.clone().negate(),right=new THREE.Vector3().crossVectors(forward,new THREE.Vector3(0,1,0)).normalize(),up=new THREE.Vector3().crossVectors(right,forward);
    const tangent=Math.tan(THREE.MathUtils.degToRad(31)),aspect=Math.max(0.25,container.clientWidth/container.clientHeight);
    let distance=3;
    for(const x of [min.x,max.x])for(const y of [min.y,max.y])for(const z of [min.z,max.z]){
        const p=new THREE.Vector3(x,y,z).sub(center);
        distance=Math.max(distance,Math.abs(p.dot(right))/(tangent*aspect)-p.dot(forward),Math.abs(p.dot(up))/tangent-p.dot(forward));
    }
    distance=distance*1.10+1;
    setCameraFieldOfView(62);camera.far=Math.max(camera.far,distance+max.distanceTo(min)+30);camera.updateProjectionMatrix();
    cameraTargetPos.copy(center).addScaledVector(direction,distance);desiredLookAtTarget.copy(center);
    targetYawOffset=targetPitchOffset=0;
    document.getElementById('inspection-caption').textContent=`Cutaway inspection · ${level==='all'?'all levels':level} · ${seats.length} seats · architecture temporarily hidden`;
}

function updateCameraModeButtons() {
    applyInspectionMode();updateSeatDetailForView();
    document.getElementById('btn-inspection-mode').setAttribute('aria-pressed',String(cameraMode==='inspection'));
    document.getElementById('btn-pov-mode').classList.toggle('active', cameraMode === 'seat');
    document.getElementById('btn-overview-mode').classList.toggle('active', cameraMode === 'overview');
    document.getElementById('btn-screen-mode').classList.toggle('active', cameraMode === 'screen');
}

/********************************************************************
 * 8. REAL-TIME TELEMETRY & CART UI UPDATER
 ********************************************************************/
// Highlight state for the seat currently under the pointer in 3D.
let currentHighlightSeatId = null;
let highlightWeakenTimer = null;

function updateHoverRingAndSelectedOutline() {
    // Hover ring follows the hovered seat (only when it is not the active POV seat).
    const hoverSeat = hoveredSeatId && hoveredSeatId !== activePOVSeatId
        ? seatRegistry.get(hoveredSeatId) : null;
    if (hoverSeat && hoverPreviewActive) {
        hoverRing.position.copy(hoverSeat.group.position);
        hoverRing.position.y += 0.06;
        hoverRing.lookAt(camera.position);
        ringMat.opacity += (0.9 - ringMat.opacity) * 0.18;
    } else {
        ringMat.opacity += (0.0 - ringMat.opacity) * 0.18;
    }
    hoverRing.visible = ringMat.opacity > 0.01;

    // Selected-cart outline: a brass ring over the first available seat in the cart.
    selectedRingMat.opacity += (0.0 - selectedRingMat.opacity) * 0.12;
    selectedRing.visible = false;
    if (selectedSeats.size > 0) {
        let anyVisible = false;
        for (const id of selectedSeats) {
            const s = seatRegistry.get(id);
            if (!s || s.isOccupied) continue;
            anyVisible = true;
            selectedRing.position.copy(s.group.position);
            selectedRing.position.y += 0.05;
            selectedRing.lookAt(camera.position);
            selectedRingMat.opacity += (0.55 - selectedRingMat.opacity) * 0.12;
            selectedRing.visible = true;
            break; // one ring at a time is enough as a persistent cart indicator
        }
        if (anyVisible) selectedRing.visible = true;
    }
}

function tryHighlightSeatIn3D(seatId) {
    if (!seatId || seatId === activePOVSeatId) return;
    const seat = seatRegistry.get(seatId);
    if (!seat || seat.isOccupied) return;

    const prev = currentHighlightSeatId && seatRegistry.get(currentHighlightSeatId);
    if (prev && prev !== seat) {
        if (prev.group) prev.group.userData.highlightUntil = 0;
    }
    currentHighlightSeatId = seatId;
    if (seat.group) {
        seat.group.userData.highlightUntil = performance.now() + 700;
        if (seat.group.userData.highlightWeaken) seat.group.userData.highlightWeaken = false;
    }
    clearTimeout(highlightWeakenTimer);
    highlightWeakenTimer = setTimeout(() => {
        if (seat && seat.group) seat.group.userData.highlightUntil = 0;
    }, 720);
}

function applyHoverLiftEachFrame() {
    const now = performance.now();
    seatRegistry.forEach((seat) => {
        if (!seat.group) return;
        const ud = seat.group.userData;
        const hoverElev = ud.hoverElevation || 0;
        let wantElev = hoverElev;
        if (ud.highlightUntil && ud.highlightUntil > now && !ud.highlightWeaken) {
            wantElev = Math.max(wantElev, 0.02);
        }
        if (ud.highlightUntil && ud.highlightUntil <= now) {
            ud.highlightWeaken = true;
            const remaining = (ud.highlightUntil - now);
            if (remaining > -200) {
                const t = 1 - Math.min(1, Math.abs(remaining) / 200);
                wantElev = t * 0.02;
            }
        }
        const prev = ud.prevElevation || 0;
        if (Math.abs(wantElev - prev) > 0.0001) {
            seat.group.position.y += (wantElev - prev);
            ud.prevElevation = wantElev;
            seat.updateTransforms();
        }
    });
}

function getSeatViewMetrics(seat) {
    const toScreen = screenCenterTarget.clone().sub(seat.eyePos);
    const distance = toScreen.length();
    const horizontalDistance = Math.hypot(toScreen.x, toScreen.z);
    const horizontalAngle = Math.atan2(-toScreen.x, -toScreen.z) * 180 / Math.PI;
    const verticalAngle = Math.atan2(toScreen.y, horizontalDistance) * 180 / Math.PI;
    return { distance, horizontalAngle, verticalAngle };
}

function renderSeatViewMetrics(seat, stateLabel = 'selected view') {
    const metrics = getSeatViewMetrics(seat);
    const geometryEstimated = Boolean(currentAudi.geometry?.estimated);
    document.getElementById('metric-seat-title').textContent = `Row ${seat.row} · Seat ${seat.num}`;
    document.getElementById('metric-seat-price').textContent = `₹${seat.price}`;
    document.getElementById('metric-seat-price-value').textContent = `₹${seat.price}`;
    document.getElementById('metric-tier-badge').textContent = seat.tier;
    document.getElementById('metric-seat-subtitle').textContent =
        `${currentAudi.name} · ${seat.tier} · ${stateLabel}`;
    document.getElementById('metric-distance').textContent = `${metrics.distance.toFixed(1)} m`;
    document.getElementById('metric-distance-desc').textContent = geometryEstimated
        ? 'Approximate · room dimensions estimated' : 'From configured room dimensions';
    const h = Math.round(metrics.horizontalAngle);
    const v = Math.round(metrics.verticalAngle);
    document.getElementById('metric-angle').textContent = `${h > 0 ? '+' : ''}${h}° H / ${v > 0 ? '+' : ''}${v}° V`;
    document.getElementById('metric-angle-desc').textContent = geometryEstimated
        ? 'Calculated to screen centre · approximate geometry'
        : 'Calculated to configured screen centre';
    document.getElementById('metric-audio').textContent = geometryEstimated
        ? 'Estimated model' : 'Configured dimensions';
    document.getElementById('metric-geometry-desc').textContent = geometryEstimated
        ? 'Room and screen dimensions are approximate' : 'Using configured room and screen dimensions';
    document.getElementById('metric-geometry-desc').title = currentAudi.reference_status_label || '';
}

function updateSeatTelemetryUI(seat) {
