            btn.className = "w-full py-2.5 rounded-xl font-display font-bold text-xs text-white bg-emerald-600 hover:bg-emerald-500 transition shadow-[0_0_15px_rgba(16,185,129,0.4)] flex items-center justify-center gap-2";
        } else {
