            btn.className = "w-full py-2.5 rounded-xl font-display font-bold text-xs text-slate-950 bg-gradient-to-r from-[#C9A84C] via-amber-300 to-amber-500 hover:brightness-110 transition shadow-[0_0_20px_rgba(201,168,76,0.4)] flex items-center justify-center gap-2";
