/********************************************************************
 * 9. VIZAG AUDITORIUM SWITCHER (PARAMETRIC REBUILD)
 ********************************************************************/
function loadVizagAuditorium(audiKey) {
    currentAudiKey = 'project';
    document.getElementById('active-theater-sub').textContent = currentAudi.sub;

    const defaultSeatId = currentAudi.defaultSeat;
    const match = defaultSeatId.match(/^(.*?)(\d+)$/);
    if (!match) return;
    const midRow = match[1];
    const midCol = Number(match[2]);

    selectedSeats.clear();
    activePOVSeatId = defaultSeatId;
    activeRowIdx = currentAudi.rows.indexOf(midRow);
    activeColNum = midCol;

    buildParametricAuditorium(currentAudi);
    selectAndFlyToSeat(midRow, midCol, false);
    // Start from a stable elevated rear view looking directly at this
    // auditorium's own screen; seat POV remains available on demand.
    setCameraMode('overview');
}

function receiveProjectSelectionState(message) {
    const unavailable = new Set(message.unavailableSeats || []);
    const booked = new Set(message.bookedSeats || []);
    const held = new Set(message.heldSeats || []);
    seatRegistry.forEach(seat => {
        seat.isOccupied = unavailable.has(seat.id) || booked.has(seat.id) || held.has(seat.id);
        seat.status = booked.has(seat.id) ? 'booked' : (held.has(seat.id) ? 'held' : (seat.isOccupied ? 'unavailable' : 'available'));
    });
    selectedSeats = new Set((message.selectedSeats || []).filter(seatId => {
        const seat = seatRegistry.get(seatId);
        return seat && !seat.isOccupied;
    }));
    document.querySelectorAll('#dom-auditorium-fallback [data-seat]').forEach(button =>
        button.classList.toggle('fallback-selected', selectedSeats.has(button.dataset.seat)));
    refreshAllSeatMaterials();
    render2DMinimap();
    if (message.activeSeat && seatRegistry.has(message.activeSeat)) {
        const active = seatRegistry.get(message.activeSeat);
        activePOVSeatId = active.id;
        if (message.cameraRequest === true) {
            selectAndFlyToSeat(active.row, active.num, false);
        } else {
            // Keep an overview or camera preset steady while the parent
            // synchronizes the seat selection and price state.
            updateSeatTelemetryUI(active);
            refreshAllSeatMaterials();
            render2DMinimap();
        }
    } else {
        updateReserveButtonAndCartUI();
    }
}

window.addEventListener('message', event => {
    if (event.origin !== location.origin || event.source !== window.parent) return;
    if (event.data?.type === 'cinewave:init' || event.data?.type === 'cinewave:selection-state') {
        receiveProjectSelectionState(event.data);
    } else if (event.data?.type === 'cinewave:camera-preset') {
        setCameraPreset(event.data.preset);
    }
});

/********************************************************************
 * 10. POINTER 360° DRAG, 3D SEAT RAYCASTING & KEYBOARD SHORTCUTS
 ********************************************************************/
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
let isDragging = false;
let dragDistance = 0;
let gesturePointerId = null;
let gestureStartedOnCanvas = false;
let prevPointer = { x: 0, y: 0 };
const tooltipEl = document.getElementById('seat-tooltip');
const activePointers = new Map();
let pinchDistance = 0;
function zoomCamera(factor) {
    const focus = desiredLookAtTarget;
    const offset = cameraTargetPos.clone().sub(focus);
    const distance = Math.max(0.1, offset.length());
    offset.multiplyScalar(THREE.MathUtils.clamp(distance * factor, 1.8, Math.max(24, auditoriumDepth * 1.25)) / distance);
    cameraTargetPos.copy(focus).add(offset);
    cameraTargetPos.x = THREE.MathUtils.clamp(cameraTargetPos.x, -auditoriumHalfWidth - 2, auditoriumHalfWidth + 2);
    cameraTargetPos.y = THREE.MathUtils.clamp(cameraTargetPos.y, 0.45, auditoriumRoomHeight + 2);
    cameraTargetPos.z = THREE.MathUtils.clamp(cameraTargetPos.z, -4, auditoriumRearWallZ + 2);
}

// Resolve the first seat mesh hit into a seat id (deduplicates the 5 seat meshes).
function seatIdFromHit(hit) {
    if (!hit) return null;
    const id = hit.object.userData?.instanceSeatIds?.[hit.instanceId]
        || (hit.object.userData && hit.object.userData.seatId);
    if (!id) return null;
    const seat = seatRegistry.get(id);
    return seat ? id : null;
}

function currentHoverSeatId() {
    pointer.x = (pointer.lastX / window.innerWidth) * 2 - 1;
    pointer.y = -(pointer.lastY / window.innerHeight) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);
    const hits = raycaster.intersectObjects(interactiveSeatMeshes, false);
    if (hits.length === 0) return null;
    const id = seatIdFromHit(hits[0]);
    return id;
}

container.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (e.pointerType === 'touch' && activePointers.size >= 2) {
        const points = [...activePointers.values()];
        pinchDistance = Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
        isDragging = false;
        gesturePointerId = null;
        gestureStartedOnCanvas = false;
        dragDistance = Infinity;
        return;
    }
    isDragging = true;
    gesturePointerId = e.pointerId;
    gestureStartedOnCanvas = e.target === renderer.domElement;
    dragDistance = 0;
    prevPointer = { x: e.clientX, y: e.clientY };
    pointer.lastX = e.clientX;
    pointer.lastY = e.clientY;
});

container.addEventListener('wheel', (e) => {
    e.preventDefault();
    zoomCamera(e.deltaY > 0 ? 1.1 : 0.9);
}, { passive: false });

window.addEventListener('pointermove', (e) => {
    pointer.lastX = e.clientX;
    pointer.lastY = e.clientY;

    if (e.pointerType === 'touch' && activePointers.has(e.pointerId)) {
        activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (activePointers.size >= 2) {
            const points = [...activePointers.values()];
            const nextDistance = Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
            if (pinchDistance > 0 && nextDistance > 0) zoomCamera(pinchDistance / nextDistance);
            pinchDistance = nextDistance;
            return;
        }
    }

    if (isDragging) {
        if (e.pointerId !== gesturePointerId) return;
        const dx = e.clientX - prevPointer.x;
        const dy = e.clientY - prevPointer.y;
        dragDistance += Math.hypot(dx, dy);
        prevPointer = { x: e.clientX, y: e.clientY };

        const sensitivity = 0.0045;
        targetYawOffset = THREE.MathUtils.euclideanModulo(targetYawOffset - dx * sensitivity + Math.PI, Math.PI * 2) - Math.PI;
        targetPitchOffset = THREE.MathUtils.clamp(targetPitchOffset - dy * sensitivity, -1.25, 1.25);

        document.getElementById('look-hint').style.opacity = '0';
        tooltipEl.classList.add('hidden');
        hideHoverPreview();
        return;
    }

    // Hover preview (no commit): show a tooltip + 3D ring after a short stillness.
    handlePointerHover(e.clientX, e.clientY);
});

function handlePointerHover(clientX, clientY) {
    pointer.x = (clientX / window.innerWidth) * 2 - 1;
    pointer.y = -(clientY / window.innerHeight) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);

    const hits = raycaster.intersectObjects(interactiveSeatMeshes, false);
    const hitSeatId = hits.length > 0 ? seatIdFromHit(hits[0]) : null;
    const seat = hitSeatId ? seatRegistry.get(hitSeatId) : null;

    if (seat) {
        container.style.cursor = seat.isOccupied ? 'not-allowed' : 'pointer';
        tooltipEl.style.left = `${clientX}px`;
        tooltipEl.style.top = `${clientY}px`;
        document.getElementById('tooltip-title').textContent = `Row ${seat.row} • Seat ${seat.num}`;
        const badgeEl = document.getElementById('tooltip-badge');
        badgeEl.textContent = seat.isOccupied ? (seat.status === 'held' ? 'HELD' : 'SOLD') : seat.tier;
        document.getElementById('tooltip-sub').textContent = seat.isOccupied
            ? (seat.status === 'held' ? 'Seat is being booked' : 'Seat already booked')
            : `₹${seat.price} • Hover to preview • Click or tap to view and select this seat`;

        // Lock the tooltip to a screen edge when it would cover the seat.
        anchorTooltipToEdge(clientX, clientY);

        // Show a non-committing hover preview of this seat's POV info.
        if (!seat.isOccupied) {
            showHoverTelemetryPreview(seat);
        }

        if (!seat.isOccupied) {
            scheduleHoverPreview(seat, clientX, clientY);
        } else {
            hideHoverPreview();
        }
        tooltipEl.classList.remove('hidden');
        return;
    }

    // Pointer is over the background: keep a short echo of this seat's
    // readout as the active preview, without committing a selection.
    if (activePOVSeatId) {
        const active = seatRegistry.get(activePOVSeatId);
        if (active && !active.isOccupied) {
            clearTimeout(hoverTelemetryTimer);
            document.getElementById('metric-tier-badge').textContent = active.tier.toUpperCase() === 'STANDARD' ? 'SEAT PREVIEW' : active.tier.toUpperCase();
            renderSeatViewMetrics(active, 'current view');
            document.getElementById('metric-tier-badge').textContent = active.tier.toUpperCase() === 'STANDARD' ? 'SEAT PREVIEW' : active.tier.toUpperCase();
            tryHighlightSeatIn3D(active.id);
        }
    }

    container.style.cursor = isDragging ? 'grabbing' : 'grab';
    tooltipEl.classList.add('hidden');
    hideHoverPreview();
}

function anchorTooltipToEdge(clientX, clientY) {
    const pad = 14;
    const tw = tooltipEl.offsetWidth || 220;
    const th = tooltipEl.offsetHeight || 70;
    const right = window.innerWidth - pad;
    const bottom = window.innerHeight - pad;
    const fitsRight = clientX + tw / 2 < right;
    const fitsBelow = clientY + th + pad < bottom;

    if (!fitsRight && !fitsBelow) {
        tooltipEl.style.transform = 'translate(-100%, -100%)';
        tooltipEl.style.left = `${clientX - tw - 8}px`;
        tooltipEl.style.top = `${clientY - th - 8}px`;
        return;
    }
    if (!fitsRight) {
        tooltipEl.style.transform = 'translate(-100%, -50%)';
        tooltipEl.style.left = `${clientX - tw - 8}px`;
        tooltipEl.style.top = `${clientY}px`;
        return;
    }
    if (!fitsBelow) {
        tooltipEl.style.transform = 'translate(-50%, -100%)';
        tooltipEl.style.left = `${clientX}px`;
        tooltipEl.style.top = `${clientY - th - 8}px`;
        return;
    }
    tooltipEl.style.transform = 'translate(-50%, -100%)';
    tooltipEl.style.left = `${clientX}px`;
    tooltipEl.style.top = `${clientY - 14}px`;
}

let hoverTelemetryTimer = null;
const HOVER_PREVIEW_ECHO_MS = 350;
let hoverEchoTimer = null;

const defaultMetricSeatTitle = 'Choose a seat';
const defaultMetricSeatPrice = '—';

function showHoverTelemetryPreview(seat) {
    clearTimeout(hoverTelemetryTimer);
    // Show this seat's estimate in the metrics panel as a preview, without changing
    // the committed active POV seat or the cart.
    if (activePOVSeatId !== seat.id) {
        renderSeatViewMetrics(seat, 'hover preview');
        document.getElementById('metric-tier-badge').textContent = seat.tier.toUpperCase() === 'STANDARD' ? 'SEAT PREVIEW' : seat.tier.toUpperCase();

        tryHighlightSeatIn3D(seat.id);
    }

    clearTimeout(hoverEchoTimer);
    hoverEchoTimer = setTimeout(() => {
        const active = seatRegistry.get(activePOVSeatId);
        if (active) {
            renderSeatViewMetrics(active, 'selected view');
        } else {
            document.getElementById('metric-seat-title').textContent = defaultMetricSeatTitle;
            document.getElementById('metric-seat-price').textContent = defaultMetricSeatPrice;
        }
        tryHighlightSeatIn3D(activePOVSeatId);
    }, HOVER_PREVIEW_ECHO_MS);
}

function scheduleHoverPreview(seat, clientX, clientY) {
    hoverPreviewSeatId = seat.id;
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(() => {
        if (hoverPreviewSeatId !== seat.id) return;
        showHoverPreview(seat, clientX, clientY);
    }, HOVER_PREVIEW_DELAY);
}

function showHoverPreview(seat, clientX, clientY) {
    if (hoverPreviewActive && hoverPreviewSeatId === seat.id) return;
    hoverPreviewActive = true;
    hoveredSeatId = seat.id;

    // Lift and gently glow the hovered seat cushion group.
    seat.group.userData.hoverElevation = 0.06;

    // Place the glow ring just above the hovered seat.
    hoverRing.position.set(0, 0, 0);
    hoverRing.position.copy(seat.group.position);
    hoverRing.position.y += 0.06;
    hoverRing.lookAt(camera.position);
    ringMat.opacity = 0.0;
    hoverRing.userData.targetOpacity = 0.9;
    hoverRing.userData.seatId = seat.id;
}

function hideHoverPreview() {
    if (!hoverPreviewActive) return;
    hoverPreviewActive = false;
    if (hoveredSeatId && seatRegistry.has(hoveredSeatId)) {
        const s = seatRegistry.get(hoveredSeatId);
        if (s.group) s.group.userData.hoverElevation = 0;
    }
    hoveredSeatId = null;
    hoverPreviewSeatId = null;
    clearTimeout(hoverTimer);
    ringMat.opacity = 0.0;
    clearTimeout(hoverTelemetryTimer);
    clearTimeout(hoverEchoTimer);
    // Restore the committed active-POV readout once the hover leaves.
    const active = seatRegistry.get(activePOVSeatId);
    if (active) updateSeatTelemetryUI(active);
    else resetTelemetryToEmpty();
}

function resetTelemetryToEmpty() {
    document.getElementById('metric-seat-title').textContent = 'Choose a seat';
    document.getElementById('metric-seat-price').textContent = '—';
    document.getElementById('metric-tier-badge').textContent = activePOVSeatId ? 'SEAT SELECTED' : 'CHOOSE SEAT';
    document.getElementById('metric-seat-subtitle').textContent = 'Seat view information';
    document.getElementById('metric-distance').textContent = '—';
    document.getElementById('metric-distance-desc').textContent = 'From screen';
    document.getElementById('metric-distance-desc').className = 'text-[10px] text-emerald-400 font-medium';
    document.getElementById('metric-angle').textContent = '—';
    document.getElementById('metric-angle-desc').textContent = 'Viewing angle';
    document.getElementById('metric-angle-desc').className = 'text-[10px] text-emerald-400 font-medium';
    document.getElementById('metric-audio').textContent = '—';
    document.getElementById('metric-geometry-desc').textContent = 'Room dimensions';
    document.getElementById('metric-exit-dist').textContent = '—';
    document.getElementById('metric-exit-name').textContent = 'Select a seat to check';
    document.getElementById('dock-seat-code').textContent = '—';
    document.getElementById('dock-seat-tier').textContent = '—';
}

window.addEventListener('pointerup', (e) => {
    activePointers.delete(e.pointerId);
    if (activePointers.size < 2) pinchDistance = 0;
    if (!isDragging || e.pointerId !== gesturePointerId) return;
    isDragging = false;
    gesturePointerId = null;

    if (dragDistance < 6 && gestureStartedOnCanvas) {
        // Tap-to-select in 3D: commit the hovered seat if there is one.
        const hitSeatId = currentHoverSeatId();
        if (hitSeatId) {
            const seat = seatRegistry.get(hitSeatId);
            if (seat) selectAndFlyToSeat(seat.row, seat.num, true);
            return;
        }

        // Otherwise re-run hover detection at the up position (single-click edge case).
        pointer.x = (e.clientX / window.innerWidth) * 2 - 1;
        pointer.y = -(e.clientY / window.innerHeight) * 2 + 1;
        raycaster.setFromCamera(pointer, camera);
        const hits = raycaster.intersectObjects(interactiveSeatMeshes, false);
        if (hits.length > 0) {
            const seatId = seatIdFromHit(hits[0]);
            const seat = seatId ? seatRegistry.get(seatId) : null;
            if (seat) selectAndFlyToSeat(seat.row, seat.num, true);
        }
    }
    gestureStartedOnCanvas = false;
    hideHoverPreview();
});

// Keyboard Arrow Keys Support for Side-Seat & Row Hopping
window.addEventListener('keydown', (e) => {
    if (['INPUT', 'SELECT', 'TEXTAREA'].includes(document.activeElement?.tagName)) return;
    if (e.key === 'ArrowLeft')  { e.preventDefault(); stepSeat(0, -1); }
    if (e.key === 'ArrowRight') { e.preventDefault(); stepSeat(0, 1); }
    if (e.key === 'ArrowUp')    { e.preventDefault(); stepSeat(1, 0); }
    if (e.key === 'ArrowDown')  { e.preventDefault(); stepSeat(-1, 0); }
});

/********************************************************************
 * 11. UI CONTROLS: FOV, VR STEREO, HOUSE LIGHTS, MODALS
 ********************************************************************/
function updateFOV(val) {
    const numVal = parseFloat(val);
    setCameraFieldOfView(numVal);
}

function toggleVRStereo() {
    isVRStereo = !isVRStereo;
    document.getElementById('vr-stereo-overlay').classList.toggle('active', isVRStereo);
    document.getElementById('btn-vr-stereo').classList.toggle('active', isVRStereo);
    if (!isVRStereo) {
        renderer.setViewport(0, 0, window.innerWidth, window.innerHeight);
        renderer.setScissorTest(false);
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
    }
}

function applyArchitecturalLightingMode() {
    const lightValues = lightingMode === 'movie'
        ? { ambient: 0.7, house: 0.04, wall: 0.08, geometric: 0.055, speaker: 0.035, aisle: 0.07, ceiling: 0.02, stage: 0.04, frame: 0.025 }
        : (lightingMode === 'preshow'
            ? { ambient: 1.15, house: 0.55, wall: 0.24, geometric: 0.18, speaker: 0.12, aisle: 0.2, ceiling: 0.22, stage: 0.12, frame: 0.07 }
            : { ambient: 1.45, house: 1.25, wall: 0.42, geometric: 0.32, speaker: 0.18, aisle: 0.32, ceiling: 0.42, stage: 0.24, frame: 0.11 });
    ambientLight.intensity = lightValues.ambient;
    houseLight.intensity = lightValues.house;
    // In small rooms the legacy full-strength screen point lights
    // overpowered the Showtime preset, even with house lights off.
    // Retain the sampled screen hues with restrained bounced light.
    const screenBounce = lightingMode === 'movie' ? 0.2 : (lightingMode === 'preshow' ? 0.45 : 0.65);
    screenLightCenter.intensity = 2.8 * screenBounce;
    screenLightLeft.intensity = screenLightRight.intensity = 2.0 * screenBounce;
    architecturalAccentMaterials.forEach(material => {
        material.emissiveIntensity = lightValues[material.userData.accentRole] ?? lightValues.wall;
    });
}

function cycleHouseLights() {
    const modes = ['movie', 'preshow', 'house'];
    lightingMode = modes[(modes.indexOf(lightingMode) + 1) % modes.length];
    const labelEl = document.getElementById('lights-label');
    applyArchitecturalLightingMode();
    if (labelEl) labelEl.textContent = lightingMode === 'movie' ? 'Showtime' : (lightingMode === 'preshow' ? 'Preshow' : 'House On');
}

function switchScreenContent(channel) {
    if (channel === 'custom') {
        document.getElementById('custom-video-modal').classList.remove('hidden');
        document.getElementById('custom-video-modal').classList.add('flex');
        return;
    }
    screenChannel = channel;
    customVideoEl.pause();
}

function closeCustomVideoModal() {
    document.getElementById('custom-video-modal').classList.add('hidden');
    document.getElementById('custom-video-modal').classList.remove('flex');
}

function applyCustomVideoUrl() {
    const url = document.getElementById('custom-video-input').value.trim();
    if (url) {
        customVideoEl.src = url;
        customVideoEl.play().catch(() => {});
        screenChannel = 'custom';
    }
    closeCustomVideoModal();
}

