let wasCompactPreview = false;
function applyResponsivePreviewLayout() {
    const compact=innerWidth<=760;
    if(compact&&!wasCompactPreview){if(!seatDetailsCollapsed)toggleSeatDetailsCollapse();if(!minimapCollapsed)toggleMinimapCollapse();}
    wasCompactPreview=compact;
