/********************************************************************
 * 12. 60FPS ANIMATION LOOP & VR STEREO RENDERING PIPELINE
 ********************************************************************/
const clock = new THREE.Clock();
const eulerRot = new THREE.Euler(0, 0, 0, 'YXZ');
const quatBase = new THREE.Quaternion();
const quatOffset = new THREE.Quaternion();
// Cameras look down local -Z while Object3D.lookAt faces +Z; using a
// camera here avoids the previous 180° flip away from the screen.
const dummyCam = new THREE.PerspectiveCamera();

function animate() {
    animationFrameId = 0;
    if (animationDestroyed || document.hidden || !container.isConnected) return;
    const now = performance.now();
    const maxFps = Number(renderer.domElement.dataset.maxFps || 30);
    if (now - lastFrameAt < 1000 / maxFps) {
        animationFrameId = requestAnimationFrame(animate);
        return;
    }
    const frameGap = now - lastFrameAt;
    // Retain fractional frame time instead of turning a 30 FPS cap
    // into a lower refresh-rate divisor on a 60 Hz display.
    lastFrameAt = now - (frameGap % (1000 / maxFps));
    const delta = Math.min(clock.getDelta(), 0.05);
    const elapsed = clock.elapsedTime;
    const cameraBlend = 1 - Math.exp(-6 * delta);
    const rotationBlend = 1 - Math.exp(-8 * delta);

    // 1. Update Live Blockbuster Movie Screen Canvas & Ambilight
    if (!reducedMotion || lastFrameAt % 500 < frameGap) renderDynamicScreenCanvas(elapsed);

    // 2. Pulse 3D Green Floor Egress Beacon Nodes toward Nearest Exit
    if (!reducedMotion) egressNodes.forEach((node, idx) => {
        const wave = Math.sin(elapsed * 5.0 - idx * 0.7) * 0.5 + 0.5;
        node.scale.setScalar(0.75 + wave * 0.65);
    });

    // 3. Subtle Projector Dust Drift
    if (dustParticles && !reducedMotion && renderQuality !== 'low') {
        dustParticles.rotation.y = Math.sin(elapsed * 0.15) * 0.04;
    }

    // 3.1 Hover preview ring slow fade per frame (smooths out timer-based pop-ins).
    updateHoverRingAndSelectedOutline();

    // 3.2 Gentle per-frame hover lift so the hovered seat settles back cleanly.
    applyHoverLiftEachFrame();

    // 4. Smoothly Interpolate Camera Position & Look Target (Screen or Exit Door)
    camera.position.lerp(cameraTargetPos, cameraBlend);
    currentLookAtTarget.lerp(desiredLookAtTarget, cameraBlend);

    const yawDelta = THREE.MathUtils.euclideanModulo(targetYawOffset - yawOffset + Math.PI, Math.PI * 2) - Math.PI;
    yawOffset += yawDelta * rotationBlend;
    pitchOffset += (targetPitchOffset - pitchOffset) * rotationBlend;

    dummyCam.position.copy(camera.position);
    dummyCam.lookAt(currentLookAtTarget);
    quatBase.copy(dummyCam.quaternion);

    eulerRot.set(pitchOffset, yawOffset, 0, 'YXZ');
    quatOffset.setFromEuler(eulerRot);
    camera.quaternion.copy(quatBase).multiply(quatOffset);

    updateSeatDetailForView();
    if((cameraMode==='inspection')!==inspectionActive)applyInspectionMode();
    // 5. Render Scene (Single View or VR Cardboard Stereo Split-Screen)
    if (!isVRStereo) {
        renderer.render(scene, camera);
    } else {
        const w = window.innerWidth;
        const h = window.innerHeight;
        const halfW = w / 2;

        camera.aspect = halfW / h;
        camera.updateProjectionMatrix();
        renderer.setScissorTest(true);

        renderer.setViewport(0, 0, halfW, h);
        renderer.setScissor(0, 0, halfW, h);
        camera.translateX(-0.032);
        renderer.render(scene, camera);

        renderer.setViewport(halfW, 0, halfW, h);
        renderer.setScissor(halfW, 0, halfW, h);
        camera.translateX(0.064);
        renderer.render(scene, camera);

        camera.translateX(-0.032);
    }
    const renderedAt = performance.now();
    if (!previewUsableAt) previewUsableAt = renderedAt;
    fpsSampleFrames++;
    if (renderedAt - fpsSampleStartedAt >= 1000) {
        measuredFps = fpsSampleFrames * 1000 / (renderedAt - fpsSampleStartedAt);
        fpsSampleStartedAt = renderedAt;
        fpsSampleFrames = 0;
    }
    animationFrameId = requestAnimationFrame(animate);
}

window.addEventListener('resize', () => {
    const w = window.innerWidth;
    const h = window.innerHeight;
    renderer.setSize(w, h);
    camera.aspect = (isVRStereo ? w / 2 : w) / h;
    if (cameraMode === 'overview') applyOverviewFieldOfView();
    else if (cameraMode === 'birdseye') applyBirdseyeFraming();
    else if (cameraMode === 'inspection') frameInspectionLevel();
    applyResponsivePreviewLayout();
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, renderQuality === 'high' ? 1.75 : (renderQuality === 'balanced' ? 1.5 : 1)));
});

// Start once after the DOM is ready. All dependencies are local and
// loaded synchronously before this script.
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootPreview, { once: true });
} else {
    bootPreview();
}

// Keep the low-memory seat-map fallback synchronized even if Three.js
// or WebGL fails before the main preview script finishes initializing.
(() => {
    let announced = false;
    window.addEventListener('message', event => {
        if (event.origin !== location.origin || event.source !== window.parent) return;
        if (!['cinewave:init', 'cinewave:selection-state'].includes(event.data?.type)) return;
        const selected = new Set(event.data.selectedSeats || []);
        const unavailable = new Set(event.data.unavailableSeats || []);
        document.querySelectorAll('#dom-auditorium-fallback [data-seat]').forEach(button => {
            const isUnavailable = unavailable.has(button.dataset.seat);
            button.disabled = isUnavailable;
            button.classList.toggle('fallback-unavailable', isUnavailable);
            if (!isUnavailable && button.dataset.seatKind) button.classList.add(button.dataset.seatKind);
            button.classList.toggle('fallback-selected', selected.has(button.dataset.seat));
        });
        if (!announced) {
            announced = true;
            window.parent.postMessage({ type: 'cinewave:ready' }, location.origin);
        }
    });
})();
